CITE_HOMES = audit.cite_homes()  # read live from the repo when this run starts

def printed(out, marker):
    """The first printed line of `out` that holds `marker`, or ""."""
    return next((line for line in out.splitlines() if marker in line), "")

def assert_cites(test, rid, line):
    """The printed refusal `rid` must cite a decision or a rule in its line, unless it is in the exempt list."""
    test.assertTrue(line, "no printed line for refusal %s" % rid)
    test.assertTrue(rid in audit.REFUSAL_UNCITED_EXEMPT or audit.cites(line, CITE_HOMES),
                    "refusal %s prints no cite: %s" % (rid, line))

_RUN_FOLDER = []
def run_folder():
    """This run's one folder (test-temp-standard), made on the first request and removed when the process exits. Every helper below takes its temp folder from it."""
    if not _RUN_FOLDER:
        _RUN_FOLDER.append(_test_temp.run_folder())
        atexit.register(shutil.rmtree, _RUN_FOLDER[0], True)
    return _RUN_FOLDER[0]

os.environ.update(LC_ALL="C", GIT_CONFIG_GLOBAL=os.devnull, GIT_CONFIG_SYSTEM=os.devnull, GIT_AUTHOR_NAME="t", GIT_AUTHOR_EMAIL="t@t",
                  GIT_COMMITTER_NAME="t", GIT_COMMITTER_EMAIL="t@t")
# CI sets none of these and a cloud session sets all three. A cloud session's values would make every `--confirm` case below meet the
# merge-role check and make a role writer write the live session's role file. A case that needs one sets it (CloudSession.cloud).
for _name in ("CLAUDE_CODE_REMOTE", "CLAUDE_CODE_REMOTE_SESSION_ID", "CLAUDE_CONFIG_DIR"):
    os.environ.pop(_name, None)

def windows_slice(x):
    """Mark a test or a leaf class as Windows-specific. MERGE_TESTS=windows-slice runs only these.
    Put it outermost on a test, so a skip decorator below it keeps the mark. Never mark a base class."""
    x._windows_slice = True
    return x

def iter_tests(suite):
    for t in suite:
        yield from iter_tests(t) if isinstance(t, unittest.TestSuite) else [t]

def select_tests(suite, mode):
    """"" keeps every test. "windows-slice" keeps the marked ones. Anything else, or an empty slice, stops the run."""
    if mode == "":
        return suite
    if mode != "windows-slice":
        raise SystemExit(f"MERGE_TESTS={mode!r}: want unset or 'windows-slice'. Nothing ran.")
    keep = [t for t in iter_tests(suite) if t.__class__.__dict__.get("_windows_slice")
            or getattr(getattr(t, t._testMethodName), "_windows_slice", False)]
    if not keep:
        raise SystemExit("MERGE_TESTS=windows-slice: no test is marked. Nothing ran.")
    return unittest.TestSuite(keep)

def select_shard(suite, value):
    """"" keeps every test. "<i>/<n>" (1 <= i <= n) keeps every n-th test from index i-1. Anything else stops the run."""
    if value == "":
        return suite
    m = re.fullmatch(r"([1-9][0-9]*)/([1-9][0-9]*)", value)
    if not m or int(m.group(1)) > int(m.group(2)):
        raise SystemExit(f"MERGE_SHARD={value!r}: want <i>/<n> with 1 <= i <= n. Nothing ran.")
    i, n = int(m.group(1)), int(m.group(2))
    keep = list(iter_tests(suite))[i - 1::n]
    if not keep:
        raise SystemExit(f"MERGE_SHARD={value!r}: this shard holds no test. Nothing ran.")
    return unittest.TestSuite(keep)

def sh(cwd, *cmd):
    r = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    assert r.returncode == 0, (cmd, r.stdout, r.stderr)
    return r.stdout.strip()

def tree_listed(cwd, path):
    """-> True when `git worktree list` names `path`. Git prints C:/ paths on Windows, so both sides are normalized."""
    norm = lambda p: os.path.normcase(os.path.realpath(p))
    out = sh(cwd, "git", "worktree", "list", "--porcelain")
    return norm(path) in {norm(l[9:]) for l in out.splitlines() if l.startswith("worktree ")}

def put(path, text):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        f.write(text)

def put_shim(path, text):
    """Write an extension-less fake program and make it runnable from PATH.

    merge.py resolves programs with shutil.which, which on Windows only matches
    PATHEXT extensions (.exe/.cmd/...), never an extension-less script. So on
    Windows we also drop a matching `<name>.cmd` beside it that re-dispatches
    to the script through the current Python.
    """
    put(path, text)
    os.chmod(path, os.stat(path).st_mode | stat.S_IXUSR)
    if os.name == "nt":
        put(path + ".cmd", '@"%s" "%%~dp0%s" %%*\n' % (sys.executable, os.path.basename(path)))

CONFIG = {
    "defaultBranch": "main",
    "regenerate": '[ -z "$MERGE_TEST_HOOK" ] || bash "$MERGE_TEST_HOOK"',
    "kinds": [{"id": "decision", "folder": "docs/decisions", "filePattern": "*.md", "prefix": "D", "pad": 3,
               "idTemplate": "{prefix}-{n}", "pendingRegex": "^id:[ \\t]*pending[ \\t]*$", "location": "frontmatter",
               "order": "filename", "numbering": "max_plus_one", "slugField": "slug", "glossField": "title"}],
    "merge": {"method": "merge", "deadlineMinutes": 5, "afterMerge": [], "deleteBranch": True},
}

def record(id_, slug):
    return f"---\nid: {id_}\nslug: {slug}\ntitle: {slug.title()}\n---\nbody\n"

class FakeHost:
    """The GitHub half, scripted. `other` is a second clone that plays a competing pusher and the merger."""
    built = True
    own_number = 7  # the lane's own PR: pr() serves its head from the branch; the lane-lint cases name it 7

    def __init__(self, root, other, branch="feat"):
        self.root, self.other, self.branch = root, other, branch
        self.checks, self.refuse, self.on_wait = (True, ""), None, None
        self.head_override, self.mergeable = None, "MERGEABLE"
        self.pr_state = "OPEN"
        self.draft = False
        self.body = ""  # the PR body gh reports: a `Drops-lines:` line in it excuses a path at the silent-undo check
        self.base, self.base_seq = "main", None  # base_seq: one base per pr() read, the last one repeats
        self.waits, self.seq, self.state = [], None, "green"  # waits: (sha, prior) per call; seq: scripted results, then self.checks
        self.batch, self.batch_error, self.batch_calls = [], None, []  # batch: the blockers batch_running reports; batch_error: raised instead; batch_calls: each (n, base) read
        self.pr_calls = []  # each n the run read through pr(): a refusal before any host read leaves it empty
        self.readies, self.ready_refuse = [], None  # readies: each n a draft confirm asked to mark ready; ready_refuse: the reason the host refuses
        self.batch_pulls, self.created, self.batch_pr_calls = {}, [], []  # batch_pulls: the batch pull requests add_pr and create_pr hold, by number; created: each create_pr; batch_pr_calls: each branch batch_pr read
        self.to_drafts, self.to_draft_refuse, self.on_to_draft = [], None, None  # to_drafts: each n a to_draft call named; to_draft_refuse: the reason the host refuses; on_to_draft: a hook a case sets, called on each call before it answers
        self.posted = []  # (n, body) of each comment post_comment was asked to make: a lane-lint PASS
        self.pulls, self.pull_list_reads = None, 0  # pulls: {number: REST row} of the other PRs a case scripts (None: the own PR only); pull_list_reads: each open_pulls call
        self.changed, self.files_error = [("README.md", "modified", 0)], None  # changed: the (path, status, additions) triples pr_files reports; files_error: raised by pr_files instead
        self.changed_files = None  # the changed_files count pr reports; None is the length of changed. The count check is the real Host's, so this fake does not check it
        self.draft_rows, self.draft_reads = None, []  # draft_rows: {sha: check-run rows} a case scripts for the draft's touched-tests read; None reads a pass. draft_reads: each read path

    def pr_files(self, n, changed=None):  # the (path, status, additions) triples of the pull request, as Host.pr_files reports them
        if self.files_error:
            raise merge.Stop(self.files_error)
        return list(self.changed)

    def review_comments(self, since):  # {PR number: [review record bodies]}: none here, so a record run reads no earlier record; the record cases pass theirs through PullsHost
        return {}

    def pages(self, rel, key=None, fields=None):  # the open pull list reviewed_read reads; none open unless a case scripts one (LeftOutHost serves its own)
        return []

    def pr(self, n):
        self.pr_calls.append(n)
        if n in self.batch_pulls:  # a batch case's pull request, read from its own entry
            return self.pr_info(n)
        if self.pulls is not None and n != self.own_number:  # a scripted PR: its row, or the 404 Host.pr raises for a PR that is not there
            if n not in self.pulls:
                raise merge.Stop(f"reading the pull request failed: HTTP 404: Not Found (#{n})")
            row = self.pulls[n]
            return {"head": row["head"]["sha"], "branch": row["head"]["ref"], "base": row["base"]["ref"], "state": row["state"].upper(),
                    "mergeable": "MERGEABLE", "merge_state": "CLEAN", "draft": bool(row["draft"]), "body": row["body"] or ""}
        head = merge.origin_head(self.root, self.branch)
        base = (self.base_seq.pop(0) if len(self.base_seq) > 1 else self.base_seq[0]) if self.base_seq else self.base
        return {"head": self.head_override or head, "branch": self.branch, "base": base, "state": self.pr_state,
                "mergeable": self.mergeable, "merge_state": "CLEAN", "draft": self.draft, "body": self.body,
                "changed_files": len(self.changed) if self.changed_files is None else self.changed_files}

    def open_pulls(self):
        """-> the open pull requests as `GET pulls` lists them: the own PR, then each scripted row that is open. Each call is one list read."""
        self.pull_list_reads += 1
        head = self.head_override or merge.origin_head(self.root, self.branch)
        own = REST.list_item(self.own_number, head, self.branch, self.base, body=self.body, draft=self.draft)
        return [own] + [row for row in (self.pulls or {}).values() if row["state"] == "open"]

    def required_names(self):
        return ["checks"]

    def batch_running(self, n, base, head=None):  # the other ready pull requests on base with a pending required check; a case sets batch
        self.batch_calls.append((n, base))
        if self.batch_error:
            raise self.batch_error
        return list(self.batch)

    def head_state(self, n):
        return self.state

    def base_state(self, base, flows):  # main's latest run is green unless a case says so (RedMainBrake)
        return "green", ""

    def wait_checks(self, n, sha, d, prior=None):
        self.waits.append((sha, prior))
        if prior is not None and self.on_wait:  # on_wait plays the rival during the wait after the claim push
            self.on_wait()
        return self.seq.pop(0) if self.seq else self.checks

    def merge(self, n, method, sha):
        if self.refuse:
            return None, self.refuse
        live = merge.origin_head(self.root, self.branch)
        if sha != live:  # GitHub's PUT names the head it merges: a head that moved is a 409, and nothing merges
            return None, f"409: #{n} is at {live[:9]}, not the {sha[:9]} the merge names"
        self.merged = True
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", self.base, f"origin/{self.base}")
        sh(o, "git", "merge", "-q", "--no-ff", "-m", f"merge #{n}", sha)
        sh(o, "git", "push", "-q", "origin", self.base)
        return sh(o, "git", "rev-parse", "HEAD"), ""

    def ready(self, n):  # the mark-ready call after a draft confirm's push -> (ok, why). On success the host clears the draft flag.
        self.readies.append(n)
        if self.ready_refuse:
            return False, self.ready_refuse
        if n in self.batch_pulls:  # the batch cases: the pull request's own draft flag clears too
            self.batch_pulls[n]["draft"] = False
        self.draft = False
        return True, ""

    def add_pr(self, n, branch, base="main", state="OPEN", draft=False, body=""):  # a pull request by number, with its head branch on origin
        self.batch_pulls[n] = {"branch": branch, "base": base, "state": state, "draft": draft, "body": body}

    def pr_info(self, n):  # the same fields as pr(), read from the entry add_pr or create_pr made
        p = self.batch_pulls[n]
        return {"head": merge.origin_head(self.root, p["branch"]), "branch": p["branch"], "base": p["base"], "state": p["state"],
                "mergeable": "MERGEABLE", "merge_state": "CLEAN", "draft": p["draft"], "body": p["body"]}

    def batch_pr(self, branch):  # the open pull request whose head is `branch`, as (n, info), or None
        self.batch_pr_calls.append(branch)
        hits = [n for n, p in self.batch_pulls.items() if p["branch"] == branch and p["state"] == "OPEN"]
        return (hits[0], self.pr_info(hits[0])) if hits else None

    def open_prs(self):  # every open pull request as [(n, info)] in number order: a rebuild finds the on-batches among them
        return [(n, self.pr_info(n)) for n in sorted(self.batch_pulls) if self.batch_pulls[n]["state"] == "OPEN"]

    def create_pr(self, branch, base, title, body, draft=False):  # the pull request holds the draft flag the caller sends
        n = 900 + len(self.created)
        self.created.append({"n": n, "branch": branch, "base": base, "title": title, "body": body, "draft": draft})
        self.add_pr(n, branch, base=base, draft=draft, body=body)
        return n

    def to_draft(self, n):  # the return to draft a drop makes on a ready batch -> (ok, why). On success the host sets the draft flag.
        self.to_drafts.append(n)
        if self.on_to_draft:
            self.on_to_draft(n)
        if self.to_draft_refuse:
            return False, self.to_draft_refuse
        if n in self.batch_pulls:
            self.batch_pulls[n]["draft"] = True
        else:
            self.draft = True
        return True, ""

    def set_body(self, n, body):
        self.batch_pulls[n]["body"] = body

    def post_comment(self, n, body):  # the fake of Host.post_comment: a comment on pull request n, recorded for the case
        self.posted.append((n, body))

    def draft_run_state(self, sha):  # the draft's touched-tests run at `sha` -> (state, lines), as Host.draft_run_state judges it
        """A case that scripts no rows (draft_rows None) reads a pass, so every other case keeps its lane. With `draft_rows`, the real judge
        reads them through DraftRunReads, and each read lands in draft_reads."""
        if self.draft_rows is None:
            return "pass", []
        return DraftRunReads(self.draft_rows, self.draft_reads).draft_run_state(sha)

DRAFT_RUN = 4300  # the run id that a draft's lane-touched-tests rows link to

def draft_row(name, conclusion="success", status="completed", job=1):
    """One check run of a draft head, as `pages("commits/<sha>/check-runs")` lists it. Its links name run DRAFT_RUN and job `job`; html_url and
    details_url both carry the link, as GitHub gives them. An unfinished run has no conclusion."""
    link = job_link(DRAFT_RUN, job)
    done = status == "completed"
    return {"id": 4000 + job, "name": name, "status": status, "conclusion": conclusion if done else None, "html_url": link, "details_url": link}

class DraftRunReads(merge.Host):
    """The real Host with its one read scripted: `pages` answers `commits/<sha>/check-runs` from `rows` (a head with no entry has no runs) and
    records each read's path in `reads`. Any other read answers []. The judge is merge.Host.draft_run_state itself, never a copy of it."""

    def __init__(self, rows, reads):
        super().__init__(required=["checks"], base="main", minute=60, now=lambda: 0.0, pause=lambda s: None)
        self.rows, self.reads = rows, reads

    def pages(self, rel, key=None, fields=None):
        self.reads.append(rel)
        m = re.fullmatch(r"commits/([0-9a-f]+)/check-runs", rel)
        return list(self.rows.get(m.group(1), [])) if m else []

def check_run_reads(reads):
    """The shas whose check runs were read, in the order read. A read of any other path is not in it."""
    return [m.group(1) for r in reads if (m := re.fullmatch(r"commits/([0-9a-f]+)/check-runs", r))]

MAILAUDIT_CHECK = "mailaudit-check"  # the required check a second checkout's stamp config names: a read of that config shows which checkout it came from

class RepoHost(FakeHost):
    """A FakeHost that main builds itself, the way `Host(cwd=...)` would: it keeps the keyword arguments it was built with."""
    def __init__(self, root, other, **built_with):
        super().__init__(root, other)
        self.built_with = built_with

    def refuse_pinned_mismatch(self):  # the real Host reads the pinned checks from GitHub; a fake has none
        return None

def second_checkout(t):
    """Make a second checkout in folder t, the way copy_repos builds one: its own origin, a main whose stamp config names MAILAUDIT_CHECK, and
    a feat that holds main's tip and has one commit of its own, so its head differs from the first checkout's. -> (co, other)."""
    os.makedirs(t, exist_ok=True)
    if not copy_repos(t):
        build_repos(t)
    co, other = os.path.join(t, "co"), os.path.join(t, "other")
    cfg = json.loads(json.dumps(CONFIG))
    cfg["merge"]["requiredChecks"] = [MAILAUDIT_CHECK]
    put(os.path.join(co, ".github/stamp.json"), json.dumps(cfg))
    sh(co, "git", "add", "-A"); sh(co, "git", "commit", "-q", "-m", "mailaudit: stamp config"); sh(co, "git", "push", "-q", "origin", "main")
    sh(co, "git", "checkout", "-q", "-B", "feat", "origin/feat"); sh(co, "git", "merge", "-q", "--no-edit", "main")
    put(os.path.join(co, "docs/decisions/mail.md"), record("pending", "mail"))
    sh(co, "git", "add", "-A"); sh(co, "git", "commit", "-q", "-m", "mailaudit: feat"); sh(co, "git", "push", "-q", "origin", "feat")
    return co, other

def checkout_key(p):
    """One key for comparing a checkout path: git prints C:/ paths on Windows and os.path prints C:\\ paths for the same folder.
    None stays None, so a missing value still fails the assert that names it."""
    return None if p is None else os.path.normcase(os.path.normpath(p))

class RepoDirRuns:
    """Mixin for a case that runs merge.main from one checkout and names another with -C or --repo-dir. Needs self.co, self.b_co, self.b_other, self.now."""

    def run_from(self, cwd, argv, host=None, lock=None, tree=None):
        """-> (rc, output, seen). merge.main runs with the process in `cwd`. With no host, main builds one: a RepoHost on the second
        checkout, kept in seen["hosts"] with the keyword arguments main gave it. default_lock(root) is recorded in seen["locks"] and gives a
        GitLock at that root. add_worktree is recorded in seen["trees"]: the one place a run makes its worktree, as open_worktree and
        lane_lint both call it. With `tree` set, the run stops there (no lint runs)."""
        seen = {"hosts": [], "locks": [], "trees": []}
        real_tree = merge.add_worktree

        def make_host(**kw):
            seen["hosts"].append(RepoHost(self.b_co, self.b_other, **kw))
            return seen["hosts"][-1]

        def make_lock(root):
            seen["locks"].append(root)
            return merge.GitLock(root, now=lambda: self.now, pause=lambda s: None)

        def open_tree(root, head):
            seen["trees"].append(root)
            if tree:
                raise merge.Stop("stopped after the worktree was named")
            return real_tree(root, head)

        out, err = io.StringIO(), io.StringIO()
        here = os.getcwd()
        os.chdir(cwd)
        try:
            with contextlib.ExitStack() as stack:
                stack.enter_context(contextlib.redirect_stdout(out))
                stack.enter_context(contextlib.redirect_stderr(err))
                stack.enter_context(unittest.mock.patch.object(merge, "Host", make_host))
                stack.enter_context(unittest.mock.patch.object(merge, "default_lock", make_lock))
                stack.enter_context(unittest.mock.patch.object(merge, "add_worktree", open_tree))
                try:
                    rc = merge.main(list(argv), host=host, lock=lock)
                except SystemExit as e:  # argparse's usage error: its code is the rc
                    rc = e.code
        finally:
            os.chdir(here)
        return rc, out.getvalue() + err.getvalue(), seen

    def spellings(self, *tail):
        """The named checkout in each spelling argparse takes, each followed by `tail`."""
        b = self.b_co
        return [["--repo-dir", b, *tail], ["--repo-dir=" + b, *tail], ["-C", b, *tail], ["-C" + b, *tail]]

    def main_subjects(self, checkout):
        """The subjects on origin/main of `checkout`, after a fetch."""
        sh(checkout, "git", "fetch", "-q", "origin")
        return sh(checkout, "git", "log", "origin/main", "--format=%s")

def wait_sites(src):
    """-> (count, in_loop) over the `wait_checks` calls in a Python source. A call inside a for or while may run many
    times, so a caller trusts the count only when in_loop is False."""
    found = []
    def walk(node, looped):
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.Call) and isinstance(child.func, ast.Attribute) and child.func.attr == "wait_checks":
                found.append(looped)
            walk(child, looped or isinstance(child, (ast.For, ast.While, ast.AsyncFor)))
    walk(ast.parse(src), False)
    return len(found), any(found)

class PipeOut(io.TextIOWrapper):
    """A Windows stdout piped to a reader (no PYTHONUTF8): cp1252, errors strict. getvalue() reads back what the pipe got."""
    def __init__(self):
        super().__init__(io.BytesIO(), encoding="cp1252", errors="strict")

    def getvalue(self):
        self.flush()
        return self.buffer.getvalue().decode("cp1252", errors="replace")

def build_repos(t):
    """In folder t: origin.git (main with the seed commit, feat one commit ahead of it), and two clones of it, co and other."""
    bare = os.path.join(t, "origin.git")
    sh(t, "git", "init", "-q", "--bare", "-b", "main", bare)
    seed = os.path.join(t, "seed")
    sh(t, "git", "clone", "-q", bare, seed)
    sh(seed, "git", "checkout", "-q", "-b", "main")
    put(os.path.join(seed, ".github/stamp.json"), json.dumps(CONFIG))
    put(os.path.join(seed, "docs/decisions/first.md"), record("D-001", "first"))
    sh(seed, "git", "add", "-A"); sh(seed, "git", "commit", "-q", "-m", "seed"); sh(seed, "git", "push", "-q", "origin", "main")
    sh(seed, "git", "checkout", "-q", "-b", "feat")
    put(os.path.join(seed, "docs/decisions/second.md"), record("pending", "second"))
    sh(seed, "git", "add", "-A"); sh(seed, "git", "commit", "-q", "-m", "feat: second"); sh(seed, "git", "push", "-q", "origin", "feat")
    for name in ("co", "other"):
        sh(t, "git", "clone", "-q", bare, os.path.join(t, name))

_TEMPLATE = []

def copy_repos(t):
    """Put build_repos(t)'s result in t without running git: copy a template built once per process, then point the two clones at the copy of origin.
    Setup was 14 git starts per test (a clone is the slow one on Windows); a copy is files only. False when the copy cannot be made or checked: the caller builds with git."""
    try:
        if not _TEMPLATE:
            root = os.path.realpath(tempfile.mkdtemp(prefix="test-merge-template-", dir=run_folder()))
            atexit.register(shutil.rmtree, root, True)
            build_repos(root)
            _TEMPLATE.append(root)
        tpl = _TEMPLATE[0]
        for name in ("origin.git", "co", "other"):
            shutil.copytree(os.path.join(tpl, name), os.path.join(t, name), symlinks=True)
        for name in ("co", "other"):
            cfg = os.path.join(t, name, ".git", "config")
            with open(cfg, encoding="utf-8", newline="") as f:
                text = f.read()
            # the clone's url as git wrote it: the path as given, with a backslash doubled (config escaping), or with forward slashes
            for form in (lambda p: p.replace("\\", "\\\\"), lambda p: p.replace("\\", "/"), lambda p: p):
                was, now = (form(os.path.join(base, "origin.git")) for base in (tpl, t))
                if text.count(was) == 1:
                    break
            else:
                raise OSError(f"the config of the clone {name} does not name the template origin once: {text!r}")
            with open(cfg, "w", encoding="utf-8", newline="") as f:
                f.write(text.replace(was, now))
        return True
    except (OSError, subprocess.SubprocessError) as e:
        print(f"test_merge: the repo template could not be copied ({e}); building this test's repos with git", file=sys.stderr)
        for name in os.listdir(t):
            shutil.rmtree(os.path.join(t, name), True)
        return False

class Env(unittest.TestCase):
    def setUp(self):
        self.t = os.path.realpath(tempfile.mkdtemp(prefix="test-merge-", dir=run_folder()))
        self.addCleanup(shutil.rmtree, self.t, True)
        self.bare = os.path.join(self.t, "origin.git")
        self.co, self.other = (os.path.join(self.t, n) for n in ("co", "other"))
        if not copy_repos(self.t):
            build_repos(self.t)
        self.now = time.time()
        self.host = FakeHost(self.co, self.other)
        self.lock = merge.GitLock(self.co, now=lambda: self.now, pause=lambda s: None)  # a retry pause is a no-op: a test never sleeps
        self.addCleanup(lambda: os.environ.pop("MERGE_TEST_HOOK", None))

    def run_merge(self, *args, host=None, lock=None, stdout=None, stderr=None, hosts=None, cwd=None):
        """-> (rc, stdout + stderr). Pass a StringIO as stderr to read the error stream on its own afterwards. `hosts` is the --root seam, one
        Host per --root string. It is passed only when merge.main takes it: on a main without it, argparse refuses --root first.
        `cwd` is the clone merge runs in; self.co when not given."""
        out, err = stdout or io.StringIO(), stderr or io.StringIO()
        prior = os.getcwd()
        os.chdir(cwd or self.co)
        seam = {"hosts": hosts} if hosts is not None and "hosts" in inspect.signature(merge.main).parameters else {}
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                rc = merge.main(list(args), host=host or self.host, lock=lock or self.lock, **seam)
        finally:
            os.chdir(prior)
        return rc, out.getvalue() + err.getvalue()

    def refs(self):
        return sh(self.co, "git", "ls-remote", "origin")

    def head(self, ref="feat"):
        return sh(self.co, "git", "ls-remote", "origin", f"refs/heads/{ref}").split("\t")[0]

    def show(self, ref, path):
        sh(self.co, "git", "fetch", "-q", "origin")
        return sh(self.co, "git", "show", f"origin/{ref}:{path}")

    def claims(self, ref="main"):
        sh(self.co, "git", "fetch", "-q", "origin")
        return sh(self.co, "git", "log", f"origin/{ref}", "--format=%s").splitlines().count("Claim record numbers")

    def lock_ref(self):
        return "refs/heads/merge-lock/main" in self.refs()

    def lock_text(self):
        sh(self.co, "git", "fetch", "-q", "origin", "refs/heads/merge-lock/main")
        return sh(self.co, "git", "log", "-1", "--format=%B", "FETCH_HEAD")

    def worktrees(self):
        return sh(self.co, "git", "worktree", "list").count("\n") + 1

    def competitor_push(self):
        o = self.other
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        put(os.path.join(o, "rival.txt"), "someone else pushed\n")
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-q", "-m", "rival"); sh(o, "git", "push", "-q", "origin", "feat")
        return sh(o, "git", "rev-parse", "HEAD")

    def main_moves(self):
        """A person pushes a commit to main that touches no path a batch touches, from the second clone."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "main", "origin/main")
        put(os.path.join(o, "elsewhere.txt"), "main moved\n")
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-q", "-m", "main moves"); sh(o, "git", "push", "-q", "origin", "main")

    def leave_no_pending_record(self):
        """feat's one pending record is removed and pushed, so a run on feat claims nothing."""
        sh(self.other, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        sh(self.other, "git", "rm", "-q", "docs/decisions/second.md")
        sh(self.other, "git", "commit", "-qm", "no pending record left"); sh(self.other, "git", "push", "-q", "origin", "feat")

    def run_args(self, *argv, host=None, hosts=None):
        """-> (rc, stdout, stderr) of merge with argv. A usage error's SystemExit is read as its code."""
        out, err = io.StringIO(), io.StringIO()
        try:
            rc = self.run_merge(*argv, host=host, hosts=hosts, stdout=out, stderr=err)[0]
        except SystemExit as e:
            rc = e.code
        return rc, out.getvalue(), err.getvalue()

    def assert_usage_error(self, *argv):
        """A usage error: rc 2, from a parser that knows every flag in argv. stderr holds no OLD_PARSER_ERRORS text and no traceback."""
        rc, out, err = self.run_args(*argv)
        self.assertEqual(rc, 2, out + err)
        for old in OLD_PARSER_ERRORS:  # a parser that has never heard of the flag says one of these
            self.assertNotIn(old, err)
        self.assertNotIn("Traceback", err)
        return out, err

    def hook(self, fn_script):
        p = os.path.join(self.t, "hook.sh")
        put(p, fn_script)
        os.environ["MERGE_TEST_HOOK"] = p

    PUSH_REFUSAL = "refused by the test"  # the text the refusing pre-receive hook prints on stderr

    def refuse_pushes(self, text=PUSH_REFUSAL):
        """Every ref update to the origin is refused from here on: a pre-receive hook that prints `text` and exits 1."""
        hook = os.path.join(self.bare, "hooks", "pre-receive")
        put(hook, f"#!/bin/sh\necho '{text}' >&2\nexit 1\n")
        os.chmod(hook, 0o755)

class Flow(Env):
    def test_preview_presses_nothing(self):
        before = self.refs()
        rc, out = self.run_merge("7")
        self.assertEqual(rc, 0, out)
        self.assertIn("PREVIEW", out)
        self.assertIn("Record-claim: D-002", out)
        self.assertEqual(self.refs(), before)
        self.assertEqual(self.worktrees(), 1)

    def test_preview_says_the_state_of_the_head_checks(self):
        self.host.state = "red: checks: fail"
        rc, out = self.run_merge("7")
        self.assertIn("head checks: red: checks: fail", out)

    def test_the_lock_outlives_every_wait_one_run_can_take(self):
        # Each wait_checks call site in merge.py is one wait, and none sits in a loop, so one run takes at most one wait per
        # site: the head, the claim, the merge commit. Limit: a helper that wraps wait_checks and is called N times undercounts.
        with open(merge.__file__, encoding="utf-8") as f:
            sites, looped = wait_sites(f.read())
        self.assertGreater(sites, 0)
        self.assertFalse(looped, "a wait_checks call sits in a loop, so the site count is no bound")
        d = merge.MERGE_DEFAULTS["deadlineMinutes"]  # the code's default deadline, set in the base config as the tool reads it
        put_base_config(self, json.dumps(dict(CONFIG, merge=dict(CONFIG["merge"], deadlineMinutes=d))))
        ttls = []
        acquire = self.lock.acquire
        self.lock.acquire = lambda b, ttl: (ttls.append(ttl), acquire(b, ttl))[1]
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        need = sites * d * 60
        self.assertGreaterEqual(ttls[0], need, "lock ttl %d s; %d waits of %d min need %d s" % (ttls[0], sites, d, need))

    def test_head_red_claims_nothing_pushes_nothing_and_frees_the_lock(self):
        before = self.refs()
        self.host.seq = [(False, "a check is red: checks: fail")]
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("a check is red: checks: fail", out)
        self.assertEqual(self.refs(), before)  # no claim push, and the lock ref is gone
        self.assertEqual(len(self.host.waits), 1)

    def test_head_pending_then_green_claims_after_the_wait(self):
        rc, out = self.run_merge("7", "--confirm")  # the fake wait returns green: one wait on the head, one on the claim
        self.assertEqual(rc, 0, out)
        (s1, p1), (s2, p2) = self.host.waits
        self.assertIsNone(p1)  # the first wait is on the head as it stands, before any push
        self.assertNotEqual(s1, s2)
        self.assertEqual(p2, s1)
        self.assertEqual(self.claims(), 1)

    def test_head_pending_then_red_claims_nothing(self):
        before = self.refs()
        self.host.seq = [(False, "a check is red: checks: fail https://x")]  # the wait saw pending, then red
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertEqual(self.refs(), before)
        self.assertEqual(self.claims(), 0)

    def test_nothing_to_claim_waits_once(self):
        self.leave_no_pending_record()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertIn("nothing to claim", out)
        self.assertEqual(len(self.host.waits), 1)

    @windows_slice
    def test_full_merge_claims_pushes_merges_syncs_cleans(self):
        # A name relative to afterMerge's own cwd (root, i.e. self.co): the command only needs to
        # prove afterMerge ran, not survive bash's own quoting of a native Windows path. An
        # absolute `self.t`-joined path here was this test's own route, not the subject: unquoted,
        # it is bash itself reading "\U" etc. as an escape and mangling the path (confirmed by
        # direct repro, independent of merge.py). See test_afterMerge_runs_in_git_bash_not_the_wsl_stub
        # for the real afterMerge defect this same line also hits.
        mark = os.path.join(self.co, "after.txt")
        cfg = dict(CONFIG, merge=dict(CONFIG["merge"], afterMerge=["echo ran > after.txt"]))
        sh(self.other, "git", "checkout", "-q", "main"); put(os.path.join(self.other, ".github/stamp.json"), json.dumps(cfg))
        sh(self.other, "git", "commit", "-qam", "cfg"); sh(self.other, "git", "push", "-q", "origin", "main")
        sh(self.co, "git", "pull", "-q", "--ff-only")
        head_takes_base(self)
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertIn("id: D-002", self.show("main", "docs/decisions/second.md"))
        self.assertEqual(self.claims(), 1)
        trailer = sh(self.co, "git", "log", "-1", "--format=%(trailers:key=Record-claim,valueonly)", "origin/main^2")
        self.assertEqual(trailer.strip(), "D-002")
        self.assertEqual(sh(self.co, "git", "rev-parse", "main"), sh(self.co, "git", "rev-parse", "origin/main"))
        self.assertTrue(os.path.exists(os.path.join(self.co, "docs/decisions/second.md")))
        self.assertTrue(os.path.exists(mark))
        self.assertNotIn("refs/heads/feat", self.refs())
        self.assertFalse(self.lock_ref())
        self.assertEqual(self.worktrees(), 1)

    @windows_slice
    def test_afterMerge_runs_in_git_bash_not_the_wsl_stub(self):
        """after_merge() runs its commands in resolve_program("bash"). On Windows, CreateProcess
        searches C:\\Windows\\System32 before PATH, and that folder holds the WSL launcher stub,
        not Git Bash (decision bare-bash-on-windows-can-resolve-to-the-wsl-stub; the lookup's one
        home is hooks/git_bash.py). A command that
        prints $OSTYPE tells the two apart: Git Bash (MSYS/MINGW) says "msys" or "msys-...", the
        WSL stub says "linux-gnu". The redirect target is a bare relative name so this case does
        not also depend on the separate native-path-quoting defect above."""
        cfg = dict(CONFIG, merge=dict(CONFIG["merge"], afterMerge=["echo $OSTYPE > ostype.txt"]))
        sh(self.other, "git", "checkout", "-q", "main"); put(os.path.join(self.other, ".github/stamp.json"), json.dumps(cfg))
        sh(self.other, "git", "commit", "-qam", "cfg"); sh(self.other, "git", "push", "-q", "origin", "main")
        sh(self.co, "git", "pull", "-q", "--ff-only")
        head_takes_base(self)
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        p = os.path.join(self.co, "ostype.txt")
        self.assertTrue(os.path.exists(p), "afterMerge did not run at all")
        with open(p) as f:
            ostype = f.read().strip()
        if os.name == "nt":
            self.assertRegex(ostype, r"msys|cygwin|mingw",
                              f"afterMerge ran under $OSTYPE={ostype!r}: that is the WSL stub, not Git Bash")
        else:
            self.assertTrue(ostype, "afterMerge ran but $OSTYPE was empty")

    def test_local_main_moves_by_fetch_when_no_worktree_holds_it(self):
        sh(self.co, "git", "checkout", "-q", "-b", "side")
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertEqual(sh(self.co, "git", "rev-parse", "main"), sh(self.co, "git", "rev-parse", "origin/main"))
        self.assertEqual(sh(self.co, "git", "rev-parse", "--abbrev-ref", "HEAD"), "side")

    def test_an_unrelated_dirty_file_does_not_block_the_fast_forward(self):
        put(os.path.join(self.co, "scratch.txt"), "x")
        sh(self.co, "git", "add", "scratch.txt")
        put(os.path.join(self.co, "docs/decisions/first.md"), "my edit\n")  # tracked, modified, not in the merge
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertEqual(sh(self.co, "git", "rev-parse", "main"), sh(self.co, "git", "rev-parse", "origin/main"))
        self.assertEqual(open(os.path.join(self.co, "scratch.txt")).read(), "x")
        self.assertEqual(open(os.path.join(self.co, "docs/decisions/first.md")).read(), "my edit\n")

    def assert_git_refuses_the_overwrite(self, rc, out, old, path, content):
        self.assertEqual(rc, 1, out)  # a failed local fast-forward exits non-zero
        self.assertIn("the merge landed. The local main did not move", out)
        self.assertIn(path, out)  # git named the blocking path
        self.assertIn(os.path.realpath(self.co), out)  # the checkout that was checked, by path (ff_main names it on both cases)
        self.assertIn("overwritten", out)  # and it was git's refusal
        self.assertNotIn("stash", out)  # never git's raw advice
        self.assertIn("Fast-forward main there by hand.", out)
        self.assertEqual(sh(self.co, "git", "rev-parse", "main"), old)
        self.assertEqual(open(os.path.join(self.co, path)).read(), content)
        self.assertIn("id: D-002", self.show("main", "docs/decisions/second.md"))

    def test_a_dirty_tracked_file_the_merge_changes_keeps_its_content_and_main_stays(self):
        o = self.other  # the PR also edits first.md, so the merge changes a file that is dirty here
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        put(os.path.join(o, "docs/decisions/first.md"), record("D-001", "first") + "pr edit\n")
        sh(o, "git", "commit", "-qam", "pr edits first"); sh(o, "git", "push", "-q", "origin", "feat")
        put(os.path.join(self.co, "docs/decisions/first.md"), "my edit\n")
        old = sh(self.co, "git", "rev-parse", "main")
        rc, out = self.run_merge("7", "--confirm")
        self.assert_git_refuses_the_overwrite(rc, out, old, "docs/decisions/first.md", "my edit\n")

    def test_an_untracked_file_at_a_path_the_merge_adds_keeps_its_content_and_main_stays(self):
        put(os.path.join(self.co, "docs/decisions/second.md"), "mine\n")  # the merge adds this path
        old = sh(self.co, "git", "rev-parse", "main")
        rc, out = self.run_merge("7", "--confirm")
        self.assert_git_refuses_the_overwrite(rc, out, old, "docs/decisions/second.md", "mine\n")

    def test_after_merge_failure_is_reported_and_the_merge_stays(self):
        sh(self.other, "git", "checkout", "-q", "main")
        cfg = dict(CONFIG, merge=dict(CONFIG["merge"], afterMerge=["exit 3"]))
        put(os.path.join(self.other, ".github/stamp.json"), json.dumps(cfg))
        sh(self.other, "git", "commit", "-qam", "cfg"); sh(self.other, "git", "push", "-q", "origin", "main")
        sh(self.co, "git", "pull", "-q", "--ff-only")
        head_takes_base(self)
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)  # a failed afterMerge exits non-zero
        self.assertIn("FAILED (exit 3). The merge landed and stays.", out)
        self.assertNotIn("refs/heads/feat", self.refs())  # the rest of the cleanup still ran
        self.assertIn("id: D-002", self.show("main", "docs/decisions/second.md"))

    def test_conflicting_pr_is_refused_before_any_claim(self):
        self.host.mergeable = "CONFLICTING"
        before = self.head()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("CONFLICTING", out)
        self.assertEqual(self.head(), before)
        self.assertFalse(self.lock_ref())

    def test_a_refusal_says_that_no_override_lifts_it(self):
        # merge.py runs as a command, after the guard, so an owner override cannot reach a Stop
        # (decision owner-override). The printed refusal says so.
        self.host.mergeable = "CONFLICTING"
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("CONFLICTING", out)
        self.assertIn("no override", out.lower())

    def test_a_closed_or_merged_pr_is_refused_before_any_claim(self):
        before = self.head()
        for state in ("CLOSED", "MERGED"):
            self.host.pr_state = state
            rc, out = self.run_merge("7", "--confirm")
            self.assertEqual(rc, 1, out)
            self.assertIn("the pull request is " + state, out)
            self.assertEqual(self.head(), before)
            self.assertFalse(self.lock_ref())

    def test_ff_main_refuses_a_commit_origin_main_does_not_hold(self):
        feat = self.head("feat")  # on origin, but never merged into origin/main
        main_before = sh(self.co, "git", "rev-parse", "refs/heads/main")
        with self.assertRaises(merge.Stop) as cm:
            merge.ff_main(self.co, "main", feat)
        self.assertIn("is not on origin/main", str(cm.exception))
        self.assertEqual(sh(self.co, "git", "rev-parse", "refs/heads/main"), main_before)

    def test_config_without_merge_method_takes_the_default_and_says_so(self):
        put_base_config(self, json.dumps(dict(CONFIG, merge={"deadlineMinutes": 5})))  # the base leaves out method
        methods = []
        real = self.host.merge
        self.host.merge = lambda n, m, sha: (methods.append(m), real(n, m, sha))[1]
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertEqual(methods, ["merge"])  # the default method
        filled = [l for l in out.splitlines() if ".github/stamp.json" in l and "method" in l]
        self.assertEqual(len(filled), 1, out)  # one line names the filled field


def without_usage(text):
    """The text with argparse's usage block left out. The block lists every flag by design, so it is no remedy."""
    kept, in_usage = [], False
    for line in text.splitlines():
        if line.startswith("usage:"):
            in_usage = True
        elif in_usage and line.startswith(" "):
            continue
        else:
            in_usage = False
            kept.append(line)
    return "\n".join(kept)

class ConfirmHead(Env):
    """`merge <pr> --confirm --head <sha>`: a relayed yes binds to the pull request's head at relay time (decision auto-mode-owner-acts,
    section Relayed Merge Yes). The head the relay named must be the live head. A moved head is refused before anything is claimed,
    locked or merged. Without --head, confirm is as Flow tests it."""

    def test_the_live_head_the_relay_named_merges(self):
        rc, out, err = self.run_args("7", "--confirm", "--head", self.head())
        self.assertEqual(rc, 0, out + err)
        self.assertTrue(getattr(self.host, "merged", False), out + err)

    def test_the_merge_call_carries_the_relayed_head(self):
        self.leave_no_pending_record()  # no claim in this run, so the sha the merge call gets is the head the relay named
        head, sent = self.head(), []
        real = self.host.merge
        self.host.merge = lambda n, m, sha: (sent.append(sha), real(n, m, sha))[1]
        rc, out, err = self.run_args("7", "--confirm", "--head", head)
        self.assertEqual(rc, 0, out + err)
        self.assertEqual(sent, [head], "the merge call did not carry the relayed head as its sha")

    def test_a_claim_push_merges_the_claim_commit_on_the_relayed_head(self):
        relayed = self.head()  # the pending record makes this run push a claim, so the head moves to the claim commit
        sent = []
        real = self.host.merge
        self.host.merge = lambda n, m, sha: (sent.append(sha), real(n, m, sha))[1]
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertEqual(rc, 0, out + err)
        self.assertEqual(len(sent), 1, out + err)
        claim = sent[0]
        self.assertNotEqual(claim, relayed, "the merge call got the relayed head, not the claim commit pushed on top of it")
        sh(self.co, "git", "fetch", "-q", "origin")
        self.assertEqual(sh(self.co, "git", "rev-parse", f"{claim}^"), relayed,
                         "the merge call's sha is not the claim commit on the relayed head")

    def test_a_moved_head_is_refused_and_says_so(self):
        relayed = self.head()
        self.competitor_push()  # the head moves after the relay
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertNotEqual(rc, 0, out + err)
        self.assertIn("moved", out + err, "the refusal does not say the head moved")
        self.assertIn("new yes", out + err, "the refusal does not say a new yes is needed")

    def test_a_moved_head_names_no_retry_target(self):
        relayed = self.head()
        live = self.competitor_push()
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertNotEqual(rc, 0, out + err)  # a run that merged would print nothing to check
        self.assertIn("moved", out + err, "no moved-head refusal to check")
        text = without_usage(out + err)
        self.assertNotIn(relayed, text, "the refusal names the relayed head in full")
        self.assertNotIn(live, text, "the refusal names the live head in full")
        self.assertNotIn("--confirm", text, "the refusal names the refused command's flag --confirm")
        self.assertNotIn("--head", text, "the refusal names the refused command's flag --head")
        self.assertNotRegex(text, r"\bmerge\s+[<\d]", "the refusal names the refused command, merge <pr>")

    def test_a_moved_head_leaves_nothing_behind(self):
        relayed = self.head()
        self.competitor_push()
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertFalse(getattr(self.host, "merged", False), out + err)
        self.assertEqual(self.claims(), 0, "a claim was pushed for a refused head")
        self.assertFalse(self.lock_ref(), "the lock was left behind")
        self.assertEqual(self.worktrees(), 1, "a worktree was left behind")

    def test_the_main_compare_refuses_a_moved_head_before_the_lock(self):
        relayed = self.head()
        self.competitor_push()  # the head moved before main's read, so main's compare refuses it first
        taken = []
        acquire = self.lock.acquire
        self.lock.acquire = lambda b, ttl: (taken.append(b), acquire(b, ttl))[1]
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertNotEqual(rc, 0, out + err)
        self.assertIn("moved", out + err, "the refusal does not say the head moved")
        self.assertEqual(taken, [], "the moved head was refused only after the lock was taken")
        self.assertEqual(self.claims(), 0, "a claim was pushed for a moved head")

    def test_the_lock_compare_refuses_a_head_that_moves_after_main_reads_it(self):
        relayed = self.head()
        read, moved = self.host.pr, []
        def pr_then_move(n):
            info = read(n)  # main's read: still the relayed head
            if not moved:
                moved.append(self.competitor_push())  # the head moves after that read and before confirm re-reads under the lock
            return info
        self.host.pr = pr_then_move
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertTrue(moved, "the head was never moved between the two reads")
        self.assertNotEqual(rc, 0, out + err)
        self.assertIn("moved", out + err, "the refusal does not say the head moved")
        self.assertFalse(getattr(self.host, "merged", False), out + err)
        self.assertEqual(self.claims(), 0, "a claim was pushed for a moved head")

    def network_drops_the_wait_after_the_claim(self):
        """The second check wait, the one after the claim push, raises a network error: the claim stays on the branch, unproven (NetStop)."""
        wait, calls = self.host.wait_checks, []
        def dropped(n, sha, d, prior=None):
            calls.append(sha)
            if len(calls) == 2:
                raise merge.NetStop("the network dropped the wait after the claim push")
            return wait(n, sha, d, prior)
        self.host.wait_checks = dropped

    def test_a_rerun_on_the_tools_own_claim_commit_proceeds(self):
        relayed = self.head()
        self.network_drops_the_wait_after_the_claim()
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)  # the claim is pushed, its result is unknown, so it stays
        self.assertNotEqual(rc, 0, out + err)
        claim = self.head()
        self.assertNotEqual(claim, relayed, "the first run pushed no claim")
        sh(self.co, "git", "fetch", "-q", "origin")
        self.assertEqual(sh(self.co, "git", "rev-parse", f"{claim}^"), relayed, "the claim is not directly on the relayed head")
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)  # the live head is the tool's own claim commit on the relayed head
        self.assertEqual(rc, 0, out + err)
        self.assertTrue(getattr(self.host, "merged", False), out + err)

    def test_a_rerun_on_the_tools_revert_of_its_claim_proceeds(self):
        relayed = self.head()
        self.host.seq = [(True, ""), (False, "a check is red after the claim push")]  # the claim wait is red, so the tool reverts its own claim
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertNotEqual(rc, 0, out + err)
        self.assertNotEqual(self.head(), relayed, "the revert did not land on the branch")
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)  # the live head is the tool's revert of its claim
        self.assertEqual(rc, 0, out + err)
        self.assertTrue(getattr(self.host, "merged", False), out + err)

    def test_a_head_that_moves_between_the_compare_and_the_put_merges_nothing(self):
        relayed = self.head()
        self.host.on_wait = self.competitor_push  # the rival lands in the wait after the claim push: after every compare, before the PUT
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertNotEqual(rc, 0, out + err)
        self.assertFalse(getattr(self.host, "merged", False), "the PUT merged a head that moved after the compare")
        self.assertEqual(self.claims(), 0, "a claim reached main")

    def test_a_rival_commit_under_a_tool_claim_refuses_a_rerun_on_the_relayed_head(self):
        relayed = self.head()
        rival = self.competitor_push()  # a rival commit on the relayed head
        self.network_drops_the_wait_after_the_claim()
        rc, out, err = self.run_args("7", "--confirm", "--head", rival)  # the tool claims on the rival commit; the claim stays
        self.assertNotEqual(rc, 0, out + err)
        claim = self.head()
        self.assertNotEqual(claim, rival, "the first run pushed no claim")
        sh(self.co, "git", "fetch", "-q", "origin")
        self.assertEqual(sh(self.co, "git", "rev-parse", f"{claim}^"), rival, "the claim is not directly on the rival commit")
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)  # the live head is the tool's claim on top of a rival commit
        self.assertNotEqual(rc, 0, out + err)
        self.assertIn("moved", out + err, "the rerun was not refused as a moved head")
        self.assertFalse(getattr(self.host, "merged", False), out + err)
        self.assertEqual(self.claims(), 0, "a claim reached main")

    def test_a_rival_commit_on_top_of_a_tool_claim_refuses_a_rerun_on_the_relayed_head(self):
        relayed = self.head()
        self.network_drops_the_wait_after_the_claim()
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)  # the tool claims on the relayed head; the claim stays
        self.assertNotEqual(rc, 0, out + err)
        claim = self.head()
        self.assertNotEqual(claim, relayed, "the first run pushed no claim")
        self.competitor_push()  # a rival commit lands on top of the tool's claim
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)  # the live head is a rival commit above the claim
        self.assertNotEqual(rc, 0, out + err)
        self.assertIn("moved", out + err, "the rerun was not refused as a moved head")
        self.assertFalse(getattr(self.host, "merged", False), out + err)
        self.assertEqual(self.claims(), 0, "a claim reached main")

    def test_a_live_head_behind_the_relayed_head_is_refused(self):
        base = self.head()
        relayed = self.competitor_push()  # the relayed head is one commit past base
        sh(self.co, "git", "fetch", "-q", "origin")  # the relayed commit is local, so the walk's log runs and finds nothing above it
        sh(self.other, "git", "push", "-q", "origin", ":feat")  # the branch is cut again at the earlier commit: the live head is behind
        sh(self.other, "git", "push", "-q", "origin", f"{base}:refs/heads/feat")
        self.assertEqual(self.head(), base, "the branch was not cut back to the earlier commit")
        rc, out, err = self.run_args("7", "--confirm", "--head", relayed)
        self.assertNotEqual(rc, 0, out + err)
        self.assertIn("moved", out + err, "the rerun was not refused as a moved head")
        self.assertFalse(getattr(self.host, "merged", False), out + err)
        self.assertEqual(self.claims(), 0, "a claim reached main")

    def test_a_head_that_is_not_40_hex_is_refused_as_bad_input(self):
        out, err = self.assert_usage_error("7", "--confirm", "--head", self.head()[:7])
        self.assertFalse(getattr(self.host, "merged", False), out + err)
        self.assertEqual(self.claims(), 0, "a claim was pushed for a bad head")
        self.assertFalse(self.lock_ref(), "the lock was left behind")

class ShallowMain(unittest.TestCase):
    """ff_main in a shallow clone of origin. The commit it moves to is on origin/main, but the clone cuts the history
    between that commit and main. The folders come from this run's run folder (test-temp-standard), not the system temp dir."""

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        cls.run_dir = _test_temp.run_folder()  # test-temp-standard; lint/test_find_copies.py RunFolderSweepTest proves the sweep once
        cls.addClassCleanup(shutil.rmtree, cls.run_dir, True)

    def setUp(self):
        self.t = tempfile.mkdtemp(dir=self.run_dir)
        build_repos(self.t)  # origin.git, and the clones seed, co and other: main holds the seed commit
        bare, other = os.path.join(self.t, "origin.git"), os.path.join(self.t, "other")
        put(os.path.join(other, "old.txt"), "old\n")
        sh(other, "git", "add", "-A"); sh(other, "git", "commit", "-q", "-m", "old"); sh(other, "git", "push", "-q", "origin", "main")
        self.old = sh(other, "git", "rev-parse", "HEAD")
        put(os.path.join(other, "new.txt"), "new\n")
        sh(other, "git", "add", "-A"); sh(other, "git", "commit", "-q", "-m", "new"); sh(other, "git", "push", "-q", "origin", "main")
        # A shallow clone of origin, then the older commit fetched at depth 1: its object is present, and the history
        # between it and main is cut. A plain --depth 1 clone lacks the object, and then ff_main stops for another reason.
        self.shallow = os.path.join(self.t, "shallow")
        error = shallow_clone.make(bare, self.shallow, self.old)
        if error:
            raise RuntimeError("shallow fixture could not be built: " + error)

    def test_the_shallow_clone_holds_the_commit_but_cuts_its_path_to_main(self):
        self.assertEqual(sh(self.shallow, "git", "rev-parse", "--is-shallow-repository"), "true")
        self.assertEqual(subprocess.run(["git", "cat-file", "-e", self.old + "^{commit}"], cwd=self.shallow).returncode, 0)
        self.assertEqual(subprocess.run(["git", "merge-base", "--is-ancestor", self.old, "refs/remotes/origin/main"],
                                        cwd=self.shallow, capture_output=True).returncode, 1)

    def test_ff_main_in_a_shallow_clone_does_not_say_the_commit_is_off_main(self):
        main_before = sh(self.shallow, "git", "rev-parse", "refs/heads/main")
        with self.assertRaises(merge.Stop) as cm:  # no Stop is a failure: ff_main must refuse to move main here
            merge.ff_main(self.shallow, "main", self.old)
        self.assertNotIn("is not on origin/main", str(cm.exception))  # the Stop may name the shallow clone, not a false claim
        self.assertEqual(sh(self.shallow, "git", "rev-parse", "refs/heads/main"), main_before, "main moved")


class ClaudeMdFlag(Env):
    """A CLAUDE.md change is flagged and only reported (decision claude-md-change-is-flagged).
    After a merge, one line per changed rule file (CLAUDE.md, .claude/CLAUDE.md, each file under output-styles/). Never a hold.

    The PR's own paths come from git, in the merge worktree and before host.merge: `git diff --name-only <base_ref>...<sha>`
    (three dots: the PR's changes, not the base's). Not `gh pr view --json files`: FakeHost has no such read. Not the merge commit's first
    parent: under the rebase method it sees one commit. Fixtures are real commits on feat, so most cases need no stub.
    The cases pin the printed lines only. Paths are literal "/" strings: git prints "/" on Windows too.

    Edge cases:
    - A rename is a change to both paths: the old path is flagged too, and git's default rename detection hides it.
    - The timeout seam: `merge.sh` is patched for the one `git diff` call whose args hold a `...` range (the PR-paths
      read). Any other call goes to the real `sh`. A case that never reaches that call fails, so a changed read cannot pass blind.
    - The match is case-insensitive on the whole rule-file path; the line prints the path as git names it."""

    def line(self, path):
        return f"merge: #7 changes {path}, a rule file every session loads."

    def flags(self, out):
        return [l for l in out.splitlines() if "a rule file every session loads" in l]

    def on_main(self, path, text):
        """Main gains a commit, pushed from the other clone, that the PR branch does not hold."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "main", "origin/main")
        put(os.path.join(o, path), text)
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", f"main: {path}"); sh(o, "git", "push", "-q", "origin", "main")

    def pr_writes(self, files, sync_main=False):
        """The PR gains one commit that writes these paths. sync_main first merges the current origin/main into feat."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        if sync_main:
            sh(o, "git", "merge", "-q", "-m", "sync main", "origin/main")
        for path, text in files.items():
            put(os.path.join(o, path), text)
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "pr: rule files"); sh(o, "git", "push", "-q", "origin", "feat")

    def assert_flagged(self, rc, out, *paths):
        """The merge landed first, so a red here means only that a flag line is wrong or missing. Then: one line per path,
        and every flag line comes after the merged-as line."""
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), out)
        self.assertCountEqual(self.flags(out), [self.line(p) for p in paths], out)
        lines = out.splitlines()
        merged_at = [i for i, l in enumerate(lines) if l.startswith("merge: #7 merged as ")]
        self.assertEqual(len(merged_at), 1, out)
        self.assertTrue(all(i > merged_at[0] for i, l in enumerate(lines) if "a rule file every session loads" in l), out)

    def test_a_merged_pr_that_adds_claude_md_is_flagged_after_the_merged_as_line(self):
        self.pr_writes({"CLAUDE.md": "new rules\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "CLAUDE.md")

    def test_a_merged_pr_that_edits_a_claude_md_already_on_main_is_flagged(self):
        self.on_main("CLAUDE.md", "rules\n")  # the owner's fear: an edit to the file main already holds
        # an added line, not a replaced one: the silent-undo scan reads a replaced line as an undo of the commit that wrote it
        self.pr_writes({"CLAUDE.md": "rules\nand one more rule\n"}, sync_main=True)
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "CLAUDE.md")

    def test_each_changed_rule_file_gets_its_own_line(self):
        self.pr_writes({".claude/CLAUDE.md": "project rules\n", "output-styles/a.md": "a\n", "output-styles/sub/b.md": "b\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, ".claude/CLAUDE.md", "output-styles/a.md", "output-styles/sub/b.md")

    def test_a_pr_that_changes_none_of_them_prints_no_line(self):
        rc, out = self.run_merge("7", "--confirm")  # the fixture PR adds docs/decisions/second.md only
        self.assert_flagged(rc, out)

    def test_a_near_miss_path_is_not_flagged(self):
        self.pr_writes({"CLAUDE.md": "rules\n", "CLAUDE.md.bak": "x\n", "output-styles.md": "x\n", "notes/output-styles/x.md": "x\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "CLAUDE.md")  # only the exact paths of the ruling

    def test_a_rule_file_that_only_main_changed_is_not_flagged(self):
        self.on_main("CLAUDE.md", "main's own change\n")  # the PR never touches it; it reaches the head only by the sync merge
        self.pr_writes({".claude/CLAUDE.md": "pr rules\n"}, sync_main=True)
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, ".claude/CLAUDE.md")

    def test_the_flag_never_holds_the_merge(self):
        self.pr_writes({"CLAUDE.md": "rules\n", ".claude/CLAUDE.md": "rules\n", "output-styles/a.md": "a\n"})
        asked = unittest.mock.patch("builtins.input", side_effect=AssertionError("the merge asked for input"))
        asked.start(); self.addCleanup(asked.stop)
        rc, out = self.run_merge("7", "--confirm")  # no extra flag, no extra word
        self.assertEqual(len(self.host.waits), 2, out)  # the head and the claim, as for any PR: no wait added
        self.assertFalse(self.lock_ref(), out)
        self.assert_flagged(rc, out, "CLAUDE.md", ".claude/CLAUDE.md", "output-styles/a.md")

    def pr_renames(self, moves):
        """Main holds each old path first. The PR merges main, then renames each (old, new). Same text, so git sees a rename."""
        for old, _ in moves:
            self.on_main(old, "".join(f"rule line {i}\n" for i in range(8)))
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat")
        sh(o, "git", "merge", "-q", "-m", "sync main", "origin/main")
        for old, new in moves:
            sh(o, "git", "mv", old, new)
        sh(o, "git", "commit", "-qm", "pr: move"); sh(o, "git", "push", "-q", "origin", "feat")

    def test_a_rename_out_of_output_styles_flags_the_old_path(self):  # F1: --name-only names the new path only
        self.pr_renames([("output-styles/x.md", "docs/x.md")])
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "output-styles/x.md")  # docs/x.md is no rule file

    def test_a_rename_into_claude_md_flags_the_new_path(self):
        self.pr_renames([("docs/y.md", "CLAUDE.md")])
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "CLAUDE.md")  # docs/y.md is no rule file

    def test_a_rename_away_from_claude_md_flags_the_old_path(self):  # F1: a moved CLAUDE.md
        self.pr_renames([("CLAUDE.md", "docs/c.md")])
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "CLAUDE.md")

    def unreadable(self, fail):
        """Patch merge.sh so the PR-paths read fails: `fail(args)` returns (rc, text) or raises. -> the list of args it saw."""
        real_sh, seen = merge.sh, []
        def stub(args, cwd=None, input=None, env=None):
            if "diff" in args and any("..." in a for a in args):
                seen.append(args)
                return fail(args)
            return real_sh(args, cwd=cwd, input=input, env=env)
        patch = unittest.mock.patch.object(merge, "sh", stub)
        patch.start(); self.addCleanup(patch.stop)
        return seen

    def assert_check_could_not_run(self, rc, out, seen):
        """The merge landed (rc 0, merged, lock free) and one line after the merged-as line says the check could not run."""
        self.assertTrue(seen, "the PR-paths read never ran, so the stub did nothing")
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), out)
        self.assertFalse(self.lock_ref(), out)
        self.assertEqual(self.flags(out), [], out)  # an unread diff names no file
        lines = out.splitlines()
        said = [i for i, l in enumerate(lines) if l.startswith("merge: #7 ") and "the rule-file check could not run" in l]
        merged_at = [i for i, l in enumerate(lines) if l.startswith("merge: #7 merged as ")]
        self.assertEqual((len(said), len(merged_at)), (1, 1), out)
        self.assertGreater(said[0], merged_at[0], out)

    def test_a_timeout_on_the_changed_paths_read_still_merges_and_says_the_check_could_not_run(self):  # F2
        self.pr_writes({"CLAUDE.md": "rules\n"})
        def slow(args):
            raise subprocess.TimeoutExpired(args, 1)
        seen = self.unreadable(slow)
        rc, out = self.run_merge("7", "--confirm")
        self.assert_check_could_not_run(rc, out, seen)

    def test_a_failed_changed_paths_read_still_merges_and_says_the_check_could_not_run(self):
        self.pr_writes({"CLAUDE.md": "rules\n"})
        seen = self.unreadable(lambda args: (128, "fatal: bad revision"))
        rc, out = self.run_merge("7", "--confirm")
        self.assert_check_could_not_run(rc, out, seen)

    def test_a_non_ascii_name_under_output_styles_is_flagged_with_its_real_name(self):  # git quotes it: "output-styles/caf\303\251.md"
        self.pr_writes({"output-styles/café.md": "a\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "output-styles/café.md")

    @windows_slice
    def test_a_name_outside_cp1252_on_a_piped_stdout_still_flags_and_runs_every_step_after_the_merge(self):  # N1: say() raises after the merge landed
        cfg = dict(CONFIG, merge=dict(CONFIG["merge"], afterMerge=["echo ran > after.txt"]))
        sh(self.other, "git", "checkout", "-q", "main"); put(os.path.join(self.other, ".github/stamp.json"), json.dumps(cfg))
        sh(self.other, "git", "commit", "-qam", "cfg"); sh(self.other, "git", "push", "-q", "origin", "main")
        sh(self.co, "git", "pull", "-q", "--ff-only")
        head_takes_base(self)
        self.pr_writes({"output-styles/日本.md": "a\n"})  # not in cp1252, unlike café
        try:
            rc, out = self.run_merge("7", "--confirm", stdout=PipeOut())
        except UnicodeEncodeError as e:
            self.fail(f"the run died with a traceback after the merge landed: {e}")
        self.assertEqual(rc, 0, out)
        self.assertTrue(getattr(self.host, "merged", False), out)
        flags = self.flags(out)
        self.assertEqual(len(flags), 1, out)  # one line, in any escaped form: only that it names the file
        self.assertTrue("output-styles/" in flags[0] and ".md" in flags[0], out)
        self.assertEqual(sh(self.co, "git", "rev-parse", "main"), sh(self.co, "git", "rev-parse", "origin/main"), out)  # ff_main ran
        self.assertTrue(os.path.exists(os.path.join(self.co, "after.txt")), out)  # afterMerge ran
        self.assertNotIn("refs/heads/feat", self.refs(), out)  # cut_branch ran
        self.assertFalse(self.lock_ref(), out)

    def test_a_lower_case_root_claude_md_is_flagged(self):  # Windows loads claude.md as CLAUDE.md
        self.pr_writes({"claude.md": "rules\n", "docs/claude.md": "x\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, "claude.md")  # docs/claude.md is no rule file

    def test_the_other_rule_file_paths_match_without_case_too(self):
        self.pr_writes({".Claude/claude.md": "rules\n", "Output-Styles/A.md": "a\n", "notes/Output-Styles/b.md": "b\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assert_flagged(rc, out, ".Claude/claude.md", "Output-Styles/A.md")

class Race(Env):
    def test_two_runs_one_lock(self):
        lock2 = merge.GitLock(self.other, now=lambda: self.now)
        for _ in range(6):
            res = []
            bar = threading.Barrier(2)
            def go(lk):
                bar.wait()
                try:
                    res.append(lk.acquire("main", 600))
                except merge.Held:
                    res.append(None)
            ts = [threading.Thread(target=go, args=(lk,)) for lk in (self.lock, lock2)]
            [t.start() for t in ts]; [t.join() for t in ts]
            self.assertEqual(len([r for r in res if r]), 1, res)
            merge.GitLock(self.co).unlock("main")

    def test_a_stale_read_still_loses_at_the_push(self):
        # Both runs read "no lock" before either wrote. Only the create-only push can tell them apart.
        self.lock.acquire("main", 600)
        lock2 = merge.GitLock(self.other, now=lambda: self.now)
        real_read, stale = lock2.read, [True]
        def stale_first_read(b, ref=None):  # the stale view answers the first read of the main ref only; the re-read after the push is real
            if stale and ref is None:
                stale.clear()
                return None
            return real_read(b, ref)
        lock2.read = stale_first_read
        with self.assertRaises(merge.Held):
            lock2.acquire("main", 600)

    def test_a_failed_reread_after_a_refused_lock_push_keeps_the_push_output(self):
        # The first read sees no lock, the push is refused, and the re-read after the refused push fails.
        self.refuse_pushes()
        real_read, reads = self.lock.read, []
        def read_then_fail(b, ref=None):  # the second read of the main ref is the re-read, and it fails
            if ref is None:
                reads.append(ref)
                if len(reads) > 1:
                    raise merge.Stop("cannot read the merge lock: the re-read failed")
            return real_read(b, ref)
        self.lock.read = read_then_fail
        with self.assertRaises(merge.Stop) as got:
            self.lock.acquire("main", 600)
        self.assertIn(self.PUSH_REFUSAL, str(got.exception))

    def test_a_netstop_from_the_reread_after_a_refused_lock_push_keeps_its_class_and_the_push_output(self):
        # The first read sees no lock, the push is refused, and the re-read after the refused push hits a network error.
        self.refuse_pushes()
        real_read, reads = self.lock.read, []
        def read_then_net_fail(b, ref=None):  # the second read of the main ref is the re-read, and it is a network NetStop
            if ref is None:
                reads.append(ref)
                if len(reads) > 1:
                    raise merge.NetStop("cannot read the merge lock: the network failed on the re-read")
            return real_read(b, ref)
        self.lock.read = read_then_net_fail
        with self.assertRaises(merge.NetStop) as got:
            self.lock.acquire("main", 600)
        self.assertIs(type(got.exception), merge.NetStop, "the re-read's NetStop was re-raised as another class")
        self.assertIn(self.PUSH_REFUSAL, str(got.exception), "the re-read's error replaced the push output")

    def test_a_held_lock_stops_a_full_run_and_touches_nothing(self):
        merge.GitLock(self.other, now=lambda: self.now).acquire("main", 600)
        before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("held", out)
        assert_cites(self, "lock-held", printed(out, "is held by"))
        self.assertEqual(self.refs(), before)

    def test_a_lock_that_is_not_ours_never_expires(self):
        sha = sh(self.co, "git", "commit-tree", "4b825dc642cb6eb9a060e54bf8d69288fbee4904", "-m", "not ours")
        sh(self.co, "git", "push", "-q", "origin", f"{sha}:refs/heads/merge-lock/main")
        self.now += 10 ** 9
        with self.assertRaises(merge.Held):
            self.lock.acquire("main", 600)

class CloudProxy(Env):
    """The cloud proxy, measured on throwaway branches (c53): a push to refs/heads/* passes, any other ref and any ref delete get
    HTTP 403, and every REST write under git/ is refused. A pre-receive hook on the origin refuses the same pushes."""
    def setUp(self):
        super().setUp()
        hook = os.path.join(self.bare, "hooks", "pre-receive")
        put(hook, "#!/bin/sh\nwhile read old new ref; do\n"
                  "  case $new in 0000000000000000000000000000000000000000) echo 'proxy: 403 delete' >&2; exit 1;; esac\n"
                  "  case $ref in refs/heads/*) ;; *) echo 'proxy: 403 ref' >&2; exit 1;; esac\n"
                  "done\n")
        os.chmod(hook, 0o755)

    def test_a_full_merge_through_the_proxy_lands_and_leaves_an_expired_lock(self):
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertNotRegex(self.refs(), r"\trefs/merge-lock/")  # the ref the proxy refuses
        self.assertLessEqual(merge.expiry_of(self.lock_text()), self.now, out)  # released by a swap to an expired commit, never deleted
        self.assertNotIn("lock release failed", out)

    def test_a_second_run_is_held_while_the_first_holds_then_takes_the_released_lock(self):
        lock2 = merge.GitLock(self.other, now=lambda: self.now)
        token = self.lock.acquire("main", 600)
        with self.assertRaises(merge.Held):
            lock2.acquire("main", 600)
        self.lock.release("main", token)
        self.assertTrue(lock2.acquire("main", 600))

    def test_unlock_through_the_proxy_leaves_a_lock_anyone_may_take(self):
        merge.GitLock(self.other, now=lambda: self.now).acquire("main", 600)
        self.assertTrue(self.lock.unlock("main"))
        self.assertEqual(merge.expiry_of(self.lock_text()), 0)
        self.assertFalse(self.lock.unlock("main"))  # a released lock is no lock: nothing is pushed again
        self.assertEqual(merge.expiry_of(self.lock_text()), 0)
        self.assertTrue(self.lock.acquire("main", 600))

    def test_unlock_with_no_lock_reports_none_and_writes_nothing(self):
        before = self.refs()
        self.assertFalse(self.lock.unlock("main"))
        self.assertEqual(self.refs(), before)

    def test_a_release_never_touches_a_lock_another_run_took(self):
        token = self.lock.acquire("main", 600)
        self.now += 601  # expired: another run takes it by a leased push
        rival = merge.GitLock(self.other, now=lambda: self.now).acquire("main", 600)
        self.lock.release("main", token)
        self.assertEqual(self.refs().split("\trefs/heads/merge-lock/main")[0].split("\n")[-1], rival)

    def test_a_live_lock_under_the_old_name_holds_a_new_run_off(self):
        old = sh(self.co, "git", "commit-tree", "4b825dc642cb6eb9a060e54bf8d69288fbee4904", "-m", merge.lock_message(600, self.now))
        hook = os.path.join(self.bare, "hooks", "pre-receive")
        os.rename(hook, hook + ".off")  # the old name was pushed by a Mac run, past no proxy
        sh(self.co, "git", "push", "-q", "origin", f"{old}:refs/merge-lock/main")
        os.rename(hook + ".off", hook)
        with self.assertRaisesRegex(merge.Held, "old name"):
            self.lock.acquire("main", 600)
        self.now += 601
        self.assertTrue(self.lock.acquire("main", 600))

    def test_a_cloud_session_picks_the_git_lock_and_a_mac_the_api_lock(self):
        with unittest.mock.patch.dict(os.environ, {"CLAUDE_CODE_REMOTE": "true"}):
            self.assertIsInstance(merge.default_lock(self.co), merge.GitLock)
        with unittest.mock.patch.dict(os.environ, {"CLAUDE_CODE_REMOTE": ""}):
            self.assertIsInstance(merge.default_lock(self.co), merge.GhLock)

class LockRetake(Env):
    """GitLock.acquire when its lease push fails (decision merge-lock). The ref is read again: a moved ref is another run's take and stays Held;
    an unchanged ref is a refused push, which stops and prints the push output. Held is a Stop too, so each refusal case asserts it is not a Held."""
    EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904"

    def released_lock(self):
        """A released lock on origin, pushed by the product's own release, so its expiry reads 0. -> its sha."""
        c, out = merge.GitLock(self.other, now=lambda: self.now).released("main", "--force-with-lease=refs/heads/merge-lock/main:")
        self.assertEqual(c, 0, out)
        self.assertEqual(merge.expiry_of(self.lock_text()), 0)
        return self.head("merge-lock/main")

    def rival_lock(self, lease):
        """Another run's live lock, pushed by the other clone under `lease`. -> its sha."""
        sha = sh(self.other, "git", "commit-tree", self.EMPTY_TREE, "-m", merge.lock_message(600, self.now))
        sh(self.other, "git", "push", "-q", lease, "origin", f"{sha}:refs/heads/merge-lock/main")
        return sha

    def move_after_first_read(self, lock):
        """`lock`'s first read of the main ref answers as the ref stands, then another run moves the ref before the push. Later reads are real.
        -> the list that receives the rival's sha once it has moved."""
        real, moved = lock.read, []
        def read(b, ref=None):
            if ref is not None or moved:
                return real(b, ref)
            got = real(b, ref)
            moved.append(self.rival_lock(f"--force-with-lease={merge.lock_ref(b)}:{got[0] if got else ''}"))
            return got
        lock.read = read
        return moved

    def assert_refused_push_stops(self):
        """acquire on a ref the origin refuses: a Stop that is not a Held, holding the push output and the lock cite."""
        with self.assertRaises(merge.Stop) as cm:
            self.lock.acquire("main", 600)
        self.assertNotIsInstance(cm.exception, merge.Held, "a refused push on an unchanged lock reads as another run's take")
        self.assertIn(self.PUSH_REFUSAL, str(cm.exception), "the Stop drops the push output")
        self.assertIn(merge.LOCK_CITE, str(cm.exception), "the Stop drops the lock cite")

    NET_DROP = "fatal: unable to access 'https://example.invalid/origin.git/': Failed to connect to example.invalid port 443 after 21 ms"

    def drop_lock_pushes(self):
        """Every push of the lock ref fails as a dropped network call: the origin never sees it, so the ref stays as it was.
        Other git calls run for real. -> (the patch, the list that receives each faked push)."""
        self.assertTrue(merge.is_net(128, self.NET_DROP), "scope: the faked push output is no network error line")
        real, pushes = merge.git, []
        def git(cwd, *args, input=None):
            if args[:1] == ("push",):
                pushes.append(args)
                return 128, self.NET_DROP
            return real(cwd, *args, input=input)
        return unittest.mock.patch.object(merge, "git", side_effect=git), pushes

    def assert_dropped_push_is_net_stop(self, pushes):
        """acquire on a push the network drops: a NetStop, which says the network failed, never that the remote refused."""
        with self.assertRaises(merge.Stop) as cm:
            self.lock.acquire("main", 600)
        self.assertTrue(pushes, "the lock push never ran, so the case proves nothing")
        self.assertIsInstance(cm.exception, merge.NetStop, "a dropped lock push reads as a refusal, not as a network stop")
        self.assertNotIn("the remote refused", str(cm.exception), "a dropped lock push says the remote refused")

    def test_a_lock_push_the_network_drops_is_a_net_stop_when_no_lock_exists(self):
        self.assertFalse(self.lock_ref())  # scope: no lock ref on origin before the take
        patch, pushes = self.drop_lock_pushes()
        with patch:
            self.assert_dropped_push_is_net_stop(pushes)
        self.assertFalse(self.lock_ref(), "the dropped push created a lock ref")

    def test_a_lock_push_the_network_drops_is_a_net_stop_over_a_released_lock(self):
        released = self.released_lock()  # scope: the released lock is on origin before the take
        patch, pushes = self.drop_lock_pushes()
        with patch:
            self.assert_dropped_push_is_net_stop(pushes)
        self.assertEqual(self.head("merge-lock/main"), released, "the dropped push moved the released lock")

    def test_a_released_lock_the_remote_refuses_stops_and_names_the_push(self):
        released = self.released_lock()
        self.refuse_pushes()
        self.assert_refused_push_stops()
        self.assertEqual(self.head("merge-lock/main"), released, "the refused push moved the released lock")

    def test_no_lock_ref_the_remote_refuses_stops_and_names_the_push(self):
        self.assertFalse(self.lock_ref())  # scope: no lock ref on origin before the take
        self.refuse_pushes()
        self.assert_refused_push_stops()
        self.assertFalse(self.lock_ref(), "the refused push created a lock ref")

    def test_a_ref_absent_at_the_read_and_present_at_the_push_is_held(self):
        self.assertFalse(self.lock_ref())  # scope: no lock ref on origin before the take
        lock2 = merge.GitLock(self.other, now=lambda: self.now)
        moved = self.move_after_first_read(lock2)
        with self.assertRaises(merge.Held):
            lock2.acquire("main", 600)
        self.assertEqual(len(moved), 1, "the rival never moved the ref, so the case proves nothing")
        self.assertEqual(self.head("merge-lock/main"), moved[0], "the Held take left the rival's lock in place")

    def test_a_released_lock_that_moves_before_the_push_is_held(self):
        self.released_lock()  # scope: the released lock is on origin before the take
        lock2 = merge.GitLock(self.other, now=lambda: self.now)
        moved = self.move_after_first_read(lock2)
        with self.assertRaises(merge.Held):
            lock2.acquire("main", 600)
        self.assertEqual(len(moved), 1, "the rival never moved the ref, so the case proves nothing")
        self.assertEqual(self.head("merge-lock/main"), moved[0], "the Held take left the rival's lock in place")

    def test_a_released_lock_is_retaken_by_one_push_and_no_delete(self):
        released = self.released_lock()
        self.assertEqual(self.head("merge-lock/main"), released)  # scope: the released lock is on origin before the take
        with unittest.mock.patch.object(merge, "git", side_effect=merge.git) as calls:
            sha = self.lock.acquire("main", 600)
        pushes = [c.args for c in calls.call_args_list if "push" in c.args]
        self.assertEqual(len(pushes), 1, pushes)
        self.assertFalse([a for args in pushes for a in args if a.startswith(":refs/heads/merge-lock/")], pushes)
        self.assertEqual(self.head("merge-lock/main"), sha)
        self.assertGreater(merge.expiry_of(self.lock_text()), self.now)

    def test_a_live_lock_is_still_held(self):
        held = merge.GitLock(self.other, now=lambda: self.now).acquire("main", 600)
        self.assertEqual(self.head("merge-lock/main"), held)  # scope: the live lock is on origin before the take
        with self.assertRaises(merge.Held):
            self.lock.acquire("main", 600)
        self.assertEqual(self.head("merge-lock/main"), held)

class Guards(Env):
    def test_moved_head_is_refused_and_nothing_is_claimed(self):
        old = self.head()
        self.competitor_push()
        moved = self.head()
        self.host.head_override = old  # gh still names the old head
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("moved", out)
        self.assertEqual(self.head(), moved)
        self.assertEqual(self.claims(), 0)
        self.assertFalse(self.lock_ref())

    def test_refused_push_leaves_origin_alone_and_never_forces(self):
        self.hook(f'git -C "{self.other}" fetch -q origin feat && git -C "{self.other}" checkout -q -B feat origin/feat '
                  f'&& echo r > "{self.other}/rival.txt" && git -C "{self.other}" add -A && git -C "{self.other}" commit -qm rival '
                  f'&& git -C "{self.other}" push -q origin feat\n')
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("refused", out)
        self.assertEqual(self.claims(), 0)
        self.assertEqual(self.head(), sh(self.other, "git", "rev-parse", "HEAD"))  # the rival commit survives
        self.assertFalse(self.lock_ref())
        self.assertEqual(self.worktrees(), 1)

    def test_red_check_reverts_the_claim(self):
        self.host.seq = [(True, ""), (False, "required check `build` is red")]  # the head is green, the claim run is red
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("`build` is red", out)
        self.assertIn("id: pending", self.show("feat", "docs/decisions/second.md"))
        self.assertEqual(self.claims("feat"), 1)  # the claim commit stays in history, reverted
        self.assertFalse(self.lock_ref())

    def test_red_check_after_a_push_in_the_wait_reverts_nothing(self):
        self.host.seq = [(True, ""), (False, "red")]
        self.host.on_wait = self.competitor_push
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("Nothing reverted", out)
        self.assertEqual(self.head(), sh(self.other, "git", "rev-parse", "HEAD"))
        self.assertIn("id: D-002", self.show("feat", "docs/decisions/second.md"))

    def test_protection_refusal_reverts_the_claim(self):
        self.host.refuse = "protected branch: 1 approving review required"
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("approving review", out)
        self.assertIn("id: pending", self.show("feat", "docs/decisions/second.md"))
        self.assertEqual(self.worktrees(), 1)

    def test_a_number_the_base_took_during_the_wait_reverts_the_claim(self):
        def base_takes_d2():
            o = self.other
            sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "main", "origin/main")
            put(os.path.join(o, "docs/decisions/third.md"), record("D-002", "third"))
            sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-q", "-m", "base takes D-002"); sh(o, "git", "push", "-q", "origin", "main")
        self.host.on_wait = base_takes_d2
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("stale", out)
        self.assertIn("id: pending", self.show("feat", "docs/decisions/second.md"))

    def test_a_failed_base_fetch_stops_the_merge_and_never_checks_a_stale_base(self):
        self.host.merged = False
        self.host.on_wait = lambda: sh(self.co, "git", "remote", "set-url", "origin", os.path.join(self.t, "gone.git"))
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1)
        self.assertIn("cannot fetch origin main", out)
        self.assertFalse(self.host.merged)

    def test_a_head_without_the_base_tip_is_refused_before_any_claim(self):  # merge-needs-current-base
        self.main_moves()
        self.host.merged = False
        before = self.refs()
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("does not hold origin/main", out)
        self.assertIn("Merge main into the branch", out)
        self.assertFalse(self.host.merged)
        self.assertEqual(self.host.waits, [])
        self.assertEqual(self.refs(), before)  # no claim push, and the lock ref is gone

    def test_a_base_that_moves_during_the_wait_reverts_the_claim_and_merges_nothing(self):
        self.host.merged = False
        self.host.on_wait = self.main_moves
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("does not hold origin/main", out)
        self.assertFalse(self.host.merged)
        self.assertIn("id: pending", self.show("feat", "docs/decisions/second.md"))

    def test_a_head_that_merged_the_moved_base_merges(self):
        self.main_moves()
        o = self.other
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat"); sh(o, "git", "merge", "-q", "--no-edit", "main"); sh(o, "git", "push", "-q", "origin", "feat")
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(self.host.merged)

    def test_the_preview_names_a_head_without_the_base_tip(self):
        self.main_moves()
        rc, out = self.run_merge("7")
        self.assertIn("base:   BEHIND:", out)
        self.assertIn("--confirm refuses it", out)
        sh(self.other, "git", "checkout", "-q", "-B", "feat", "origin/feat"); sh(self.other, "git", "merge", "-q", "--no-edit", "main"); sh(self.other, "git", "push", "-q", "origin", "feat")
        rc, out = self.run_merge("7")
        self.assertIn("base:   holds main's tip", out)

    def test_the_claim_commit_works_with_no_git_identity(self):
        info = self.host.pr(7)
        tmp, wt = merge.open_worktree(self.co, info, "main")
        keep = {k: os.environ.pop(k) for k in ("GIT_AUTHOR_NAME", "GIT_AUTHOR_EMAIL", "GIT_COMMITTER_NAME", "GIT_COMMITTER_EMAIL")}
        cfg_key = re.compile(r"GIT_CONFIG_(COUNT|KEY_\d+|VALUE_\d+)$")  # append to keys already set, never replace them
        keep_cfg = {k: v for k, v in os.environ.items() if cfg_key.match(k)}
        n = int(os.environ.get("GIT_CONFIG_COUNT", "0"))
        os.environ.update(GIT_CONFIG_COUNT=str(n + 1), **{"GIT_CONFIG_KEY_%d" % n: "user.useConfigOnly", "GIT_CONFIG_VALUE_%d" % n: "true"})
        try:
            trailer = merge.do_claim(wt, ".github/stamp.json", "origin/main")
            self.assertEqual(len(merge.commit_claim(wt, trailer)), 40)
        finally:
            for k in [k for k in os.environ if cfg_key.match(k)]:
                os.environ.pop(k)
            os.environ.update(keep_cfg)
            os.environ.update(keep)
            merge.drop_worktree(self.co, tmp, wt)

SCOPE_SCRIPT = os.path.join(HERE, "..", ".github", "scripts", "ci-scope.sh")  # the real script: the one home of which jobs read which paths
CHECKS_YML = ("name: checks\non: pull_request\njobs:\n"  # checks-merge-install comes first: a test that appends steps puts them in `checks`, the last job
             "  checks-merge-install:\n    runs-on: ubuntu-latest\n    steps:\n"
             "      - name: Merge install suite\n        run: python3 hooks/x.py\n"
             "  checks:\n    runs-on: ubuntu-latest\n    steps:\n"
             "      - name: Record slug check\n        run: python3 lint/check_slugs.py\n"
             "      - name: Guide reader suite\n        run: python3 hooks/test_reads_guide.py\n")
SLUG_LINT = '''import collections, os, re, sys
seen = collections.defaultdict(list)
for d, _, names in os.walk("docs"):
    for n in names:
        if n.endswith(".md"):
            m = re.search(r"^slug: (.+)$", open(os.path.join(d, n), encoding="utf-8").read(), re.M)
            if m:
                seen[m.group(1)].append(n)
bad = {k: v for k, v in seen.items() if len(v) > 1}
print(bad or "ok")
sys.exit(1 if bad else 0)
'''
DOC_SUITE = '''import os, sys
path = os.path.join("docs", "guide.md")  # a checks suite that reads one tracked doc, named in no list
sys.exit(1 if os.path.exists(path) and "BROKEN" in open(path, encoding="utf-8").read() else 0)
'''

class ScopedRepo:
    """The fixture for a repo whose CI is the real ci-scope.sh and a checks workflow. scoped() puts them on main, and feat then holds
    main's tip. on() commits a file set to a branch. SmallBaseMove and ExpressPath both use these: neither copies them."""

    def scoped(self, workflow=CHECKS_YML, scope=True, name="checks.yml"):
        """Main and feat both gain the CI files, the workflow under the file name `name`; feat then holds main's tip."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", "main", "origin/main")
        if scope:
            with open(SCOPE_SCRIPT, encoding="utf-8") as f:
                put_lf(os.path.join(o, ".github/scripts/ci-scope.sh"), f.read())
        put(os.path.join(o, ".github/workflows", name), workflow)
        put(os.path.join(o, "landed-dirs.txt"), "hooks\n")
        put(os.path.join(o, "lint/check_slugs.py"), SLUG_LINT)
        put(os.path.join(o, "hooks/test_reads_guide.py"), DOC_SUITE)
        put(os.path.join(o, "hooks/x.py"), "X = 1\n")
        put(os.path.join(o, "docs/shared.md"), "one\ntwo\nthree\nfour\nfive\n")
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", "ci files"); sh(o, "git", "push", "-q", "origin", "main")
        sh(o, "git", "checkout", "-q", "-B", "feat", "origin/feat"); sh(o, "git", "merge", "-q", "--no-edit", "main"); sh(o, "git", "push", "-q", "origin", "feat")

    def on(self, branch, files, start=None):
        """Commit `files` to `branch` and push it. The branch is made from origin/`start` when given, else from origin/`branch`: a new branch needs `start`."""
        o = self.other
        sh(o, "git", "fetch", "-q", "origin"); sh(o, "git", "checkout", "-q", "-B", branch, f"origin/{start or branch}")
        for path, text in files.items():
            (put_lf if path.endswith(".sh") else put)(os.path.join(o, path), text)  # bash reads a CRLF script as a bad option on Windows
        sh(o, "git", "add", "-A"); sh(o, "git", "commit", "-qm", f"{branch} moves"); sh(o, "git", "push", "-q", "origin", branch)

class SmallBaseMove(ScopedRepo, Env):
    """Main moved, but only by paths that no CI job of the batch reads (merge-needs-current-base, step c150).
    The real ci-scope.sh and the real bin/ci-job run against a fixture workflow whose `checks` job holds one cross-file lint:
    no two docs share a slug. hooks/test_reads_guide.py is a checks suite outside --lint that reads docs/guide.md."""

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        cls.run_dir = _test_temp.run_folder()  # test-temp-standard: the plain repos below are made in this run's folder
        cls.addClassCleanup(shutil.rmtree, cls.run_dir, True)

    def batch_repo(self):
        """A plain repo: main at a base commit, and branch n with one commit, the batch head. -> (repo, the batch head's sha)."""
        repo = tempfile.mkdtemp(dir=self.run_dir)
        sh(repo, "git", "init", "-q")
        sh(repo, "git", "checkout", "-q", "-B", "main")
        put(os.path.join(repo, "base.txt"), "base\n"); sh(repo, "git", "add", "-A"); sh(repo, "git", "commit", "-qm", "base")
        sh(repo, "git", "checkout", "-q", "-b", "n"); put(os.path.join(repo, "n.txt"), "N\n")
        sh(repo, "git", "add", "-A"); sh(repo, "git", "commit", "-qm", "N head")
        return repo, sh(repo, "git", "rev-parse", "HEAD")

    def next_push(self, repo, n_head):
        """A commit on the batch head, pushed after main moved. -> its sha."""
        sh(repo, "git", "checkout", "-q", "-B", "n1", n_head); put(os.path.join(repo, "n1.txt"), "N+1\n")
        sh(repo, "git", "add", "-A"); sh(repo, "git", "commit", "-qm", "N+1")
        return sh(repo, "git", "rev-parse", "HEAD")

    def holds_base_without_ci(self, repo, base_ref, sha):
        """-> holds_base's (refusal, why), and asserts that no lint and no suite ran: the green run stands on the merge's tree alone."""
        calls = []
        real = merge.sh
        def spy(args, *a, **k):
            calls.append(" ".join(args))
            return real(args, *a, **k)
        with unittest.mock.patch.object(merge, "sh", spy):
            refusal, why = merge.holds_base(repo, base_ref, sha)
        self.assertFalse([c for c in calls if merge.CI_JOB in c or merge.CI_SCOPE in c], calls)
        return refusal, why

    def test_main_merged_from_the_batch_head_keeps_the_green_run_for_the_next_push(self):
        repo, n_head = self.batch_repo()
        sh(repo, "git", "checkout", "-q", "main"); sh(repo, "git", "merge", "-q", "--no-ff", "-m", "Merge n", "n")  # main has N head's tree
        n1 = self.next_push(repo, n_head)
        refusal, why = self.holds_base_without_ci(repo, "main", n1)
        self.assertIsNone(refusal, refusal)
        self.assertTrue(why)

    def test_main_with_an_empty_commit_keeps_the_green_run_for_the_next_push(self):
        repo, n_head = self.batch_repo()
        sh(repo, "git", "checkout", "-q", "main"); sh(repo, "git", "commit", "-q", "--allow-empty", "-m", "empty main commit")
        n1 = self.next_push(repo, n_head)
        refusal, why = self.holds_base_without_ci(repo, "main", n1)
        self.assertIsNone(refusal, refusal)
        self.assertTrue(why)

    def test_main_that_moved_and_came_back_does_not_keep_the_green_run_for_the_lane(self):
        # The lane is cut at M0. Main adds c.txt (M1), then reverts it (M2, tree M0). CI on the lane tested merge(lane, M1), which holds c.txt.
        repo, n_head = self.batch_repo()
        sh(repo, "git", "checkout", "-q", "main")
        put(os.path.join(repo, "c.txt"), "c\n"); sh(repo, "git", "add", "-A"); sh(repo, "git", "commit", "-qm", "M1 adds c")
        sh(repo, "git", "rm", "-q", "c.txt"); sh(repo, "git", "commit", "-qm", "M2 reverts c")
        refusal, _ = merge.holds_base(repo, "main", n_head)
        self.assertIsNotNone(refusal)
        self.assertIn("does not hold main", refusal)

    def test_a_batch_rename_of_a_path_main_changed_is_a_shared_path(self):
        # --no-renames in small_base_move: the batch's rename names its old path too, so main's change to base.txt is shared.
        # With rename detection the batch names moved.txt only, the shared check passes, and the green run stands.
        repo, _ = self.batch_repo()
        sh(repo, "git", "mv", "base.txt", "moved.txt"); sh(repo, "git", "commit", "-qm", "N renames base")
        n_head = sh(repo, "git", "rev-parse", "HEAD")
        base = sh(repo, "git", "merge-base", "main", n_head)
        sh(repo, "git", "checkout", "-q", "main"); put(os.path.join(repo, "base.txt"), "main changed\n")
        sh(repo, "git", "add", "-A"); sh(repo, "git", "commit", "-qm", "main changes base")
        scope = sh(repo, "git", "diff", "--name-status", "-M", base, n_head)
        self.assertIn("R100\tbase.txt\tmoved.txt", scope, "the batch is not an exact rename, so the case proves nothing:\n" + scope)
        with tempfiles_in_run_folder():
            ok, why = merge.small_base_move(repo, "main", n_head)
        self.assertFalse(ok, "the batch's rename hid main's change to base.txt, so the green run stands: " + why)
        self.assertIn("main and the batch both change base.txt", why, "the batch's rename hid main's change to base.txt from the shared-path check")

    def refused(self):
        self.host.merged = False
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 1, out)
        self.assertIn("does not hold origin/main", out)
        self.assertIn("Merge main into the branch", out)
        self.assertFalse(self.host.merged, out)
        return out

    def test_a_docs_only_main_move_keeps_the_green_run(self):
        self.scoped()
        self.on("main", {"docs/guide.md": "# Guide\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(self.host.merged, out)
        self.assertNotIn("does not hold", out)
        self.assertIn("main moved by 1 commit touching only paths no job of this batch reads; the lints pass on the merge", out)
        self.assertIn("# Guide", self.show("main", "docs/guide.md"))

    def test_a_docs_only_move_during_the_wait_keeps_the_green_run(self):
        self.scoped()
        self.host.on_wait = lambda: self.on("main", {"docs/late.md": "# Late\n"})
        rc, out = self.run_merge("7", "--confirm")
        self.assertEqual(rc, 0, out)
        self.assertTrue(self.host.merged, out)

    def test_the_preview_says_a_docs_only_move_keeps_the_green_run(self):
        self.scoped()
        self.on("main", {"docs/guide.md": "# Guide\n"})
        rc, out = self.run_merge("7")
        self.assertIn("base:   main moved by 1 commit touching only paths no job of this batch reads", out)
        self.assertNotIn("BEHIND", out)

