        self.on("feat", {"docs/shared.md": "one changed\ntwo\nthree\nfour\nfive\n"})
        self.on("main", {"docs/shared.md": "one\ntwo\nthree\nfour\nfive changed\n"})  # merges clean, but one path
        self.assertIn("docs/shared.md", self.refused())

