    def test_a_batch_without_lanes_reads_no_open_prs_and_prints_no_lane_line(self):
        rc, out = self.go()  # feat holds no merge commit
        self.assertEqual(rc, 0, out)
        self.assertEqual(self.host.open_calls, 0)
