# c53: the merge tool reads and merges through the REST API (`gh api`), because a cloud session answers GraphQL with HTTP 403.
# The fake gh logs one line per call: METHOD, the route under repos/<owner>/<repo>, the fields sorted, then --paginate or --slurp.
# A read of the pull request after the merge call carries the suffix "after-merge".
MERGE_CALL = "PUT pulls/7/merge"
STATE_READ = "GET pulls/7 after-merge"
LIST_CALL = "GET pulls "
CHECKS_CALL = "GET commits/"
REPO_CALL = "GET (repo)"
NOT_MERGEABLE = rest_err(405, "Pull Request is not mergeable")
NOT_FOUND = rest_err(404, "Not Found")

# The rate waits, in seconds, when GitHub gives no reset time: one per retry. The last one is also the cap on any wait.
# The retry count is 3. The ladder waits 21 minutes in all.
RATE_LADDER = [60, 300, 900]
_HTTP_TEXT = {200: "OK", 403: "Forbidden", 404: "Not Found", 422: "Unprocessable Entity", 429: "Too Many Requests", 500: "Internal Server Error", 502: "Bad Gateway"}

def http_code_of(text):
    """The status in gh's own error line, `(HTTP 403)` or `HTTP 422: ...`. Else 400."""
    found = re.findall(r"HTTP (\d{3})", text)
    return int(found[-1]) if found else 400

def gh_i(code, body, **headers):
    """What `gh api -i` prints (measured on gh 2.98.0, on 200 and 403, with and without --jq): the status line, the headers with
    Go-canonical names, a blank line, then the body and, on a failure, gh's own error line after it. `--jq` does not strip the block. A
    keyword's underscores are dashes: Retry_After is `Retry-After`. GitHub itself answers HTTP/2.0, so the status line is too."""
    lines = [f"HTTP/2.0 {code} {_HTTP_TEXT.get(code, 'Error')}", "Content-Type: application/json; charset=utf-8",
             *(f"{k.replace('_', '-')}: {v}" for k, v in headers.items())]
    return "\r\n".join(lines) + "\r\n\r\n" + body

def without_include(args):
    """`gh api`'s args with -i/--include left out, so a fake that reads them by position keeps working wherever the build puts the flag."""
    return [x for x in args if x not in ("-i", "--include")]

class Clock:
    """A fake clock for the rate waits: each pause moves it on and records the wait, so a 900 s wait costs no time and expiry arithmetic is real.
    now() and pause() are the seams every gh caller already takes."""
    def __init__(self, t=1000.0):
        self.t, self.pauses = t, []

    def now(self):
        return self.t

    def pause(self, seconds):
        self.pauses.append(seconds)
        self.t += seconds

def drop_config(env):
    """Remove .github/stamp.json from main and feat, as in 5 of the owner's 8 repos. Then pull main into env.co."""
    o = env.other
    for b in ("main", "feat"):
        sh(o, "git", "fetch", "-q", "origin")
        sh(o, "git", "checkout", "-q", "-B", b, f"origin/{b}")
        sh(o, "git", "rm", "-q", ".github/stamp.json")
        sh(o, "git", "commit", "-qm", f"no config on {b}")
        sh(o, "git", "push", "-q", "origin", b)
    sh(env.co, "git", "pull", "-q", "--ff-only")
    head_takes_base(env)

def stamp_marker(env):
    """Point merge.STAMP at a stub that writes a file when it runs. -> that file's path; absent unless stamp ran."""
    mark = os.path.join(env.t, "stamp-ran")
    fake = os.path.join(env.t, "marker-stamp.mjs")
    put(fake, 'import { writeFileSync } from "node:fs";\nwriteFileSync(process.env.STAMP_MARK, "ran");\n')
    for p in (unittest.mock.patch.object(merge, "STAMP", fake), unittest.mock.patch.dict(os.environ, {"STAMP_MARK": mark})):
        p.start(); env.addCleanup(p.stop)
    return mark

def gh_case_setup(test):
    """What every fake-gh case starts with: the shim on PATH, the wait's clock at zero, and a head whose one check is green. GhHalf, RestRoutes and SupersededRuns share it."""
    install_gh_shim(test)
    test.ticks, test.paused, test.at_pause = 0, [], []
    GhHalf.set(test, checks_seq=[[("checks", "pass", "")]])

WS_PROBE = " \t\n\r\f\v"  # the whitespace characters a \s repeat can take

def adjacent_whitespace_repeats(pattern):
    """-> where in `pattern` a repeat that can take a whitespace run is followed, with only skippable items between, by a repeat that can take a whitespace run too.
    Both repeats then take the same run, so a search backtracks over it once for each split between them. Reads the parsed pattern, never its source text, and reads no clock."""
    try:
        from re import _parser as sre_parse, _compiler as sre_compile  # Python 3.11 and later
    except ImportError:  # Python 3.10 and earlier
        import sre_parse, sre_compile
    repeats = (sre_parse.MAX_REPEAT, sre_parse.MIN_REPEAT)

    def begins_ws(body):
        """True when the sub-pattern `body` can consume a whitespace character at its first position."""
        compiled = sre_compile.compile(body)
        for c in WS_PROBE:
            for tail in ("", c, "x", "#2390"):
                m = compiled.match(c + tail)
                if m is not None and m.end() > 0:
                    return True
        return False

    def sub_patterns(value):
        if isinstance(value, sre_parse.SubPattern):
            yield value
        elif isinstance(value, (tuple, list)):
            for v in value:
                yield from sub_patterns(v)

    found = []

    def walk(seq, where):
        items = list(seq.data)
        for i, (op, av) in enumerate(items):
            if op not in repeats or not begins_ws(av[2]):
                continue
            for j in range(i + 1, len(items)):
                op2, av2 = items[j]
                if op2 in repeats and begins_ws(av2[2]):
                    found.append(f"{where}: items {i} and {j}")
                    break
                if not (op2 in repeats and av2[0] == 0):  # a required item stops the scan: nothing skippable lies between
                    break
        for i, (op, av) in enumerate(items):
            for sub in sub_patterns(av):
                walk(sub, f"{where}/{i}")

    walk(sre_parse.parse(pattern), "top")
    return found

class CloseKeywordReason(Env):
    """A reason flag's reason lands in the merge commit (lift_message), and GitHub closes an issue that a commit names after a closing keyword.
    So a reason with a closing keyword before an issue ref is refused, after argparse and before the lock, any host read and any write.
    The refusal gives the reword example and never prints the closing form. A closing word before an issue URL is refused the same way. A keyword with no ref or URL right after it is allowed."""
    FLAGS = ("--base-red-ok", "--undo-check-unknown-ok")
    NINE = ("close", "closes", "closed", "fix", "fixes", "fixed", "resolve", "resolves", "resolved")
    REFUSED = ([f"{word} #2390" for word in NINE]
               + ["FiXeS #2390", "CLOSED #2390", "rEsOlVeS #2390", "fixes: #2390", "fixes:#2390", "fixes#2390", "Resolves:   #2390",
                  "fixes shivinate7/claude-settings#2390", "closes owner/repo#2390", "base red; this fixes #2390 too",
                  "fixes   #2390", "fixes : #2390", "fixes\t#2390", "fixes\n#2390"])
    REFUSED_URL = ([f"{word} https://github.com/o/r/issues/2390" for word in NINE]
                   + ["Fixes: https://github.com/o/r/issues/2390", "resolves http://github.com/o/r/issues/2390",
                      "closed www.github.com/o/r/issues/2390", "fix https://github.com/o/r/pull/2390",
                      "fixes https://www.github.com/o/r/issues/2390", "closes:https://github.com/shivinate7/claude-settings/issues/2390",
                      "base red; this fixes https://github.com/o/r/issues/2390 too"])
    ALLOWED = ("PR #2390", "#2390", "fix the base", "fix the base, see #2390", "prefixes #2390", "cause and fix: PR 2390",
               "see https://github.com/o/r/issues/2390", "fix https://example.com/issues/5",
               "fixtures/x#12", "prefix fixtures/x#12")
    REWORD = "cause and fix: PR 2390"  # the example the refusal gives
    LONG_RUN = " " * 20000  # the whitespace run after a keyword: one home for the long-run cases

    def refused_each(self, flag, reasons):
        """Each refused reason, given with `flag`, stops before the host read. The PR is CLOSED, so a run that reads it stops on a CLOSED line instead."""
        self.host.pr_state = "CLOSED"
        for reason in reasons:
            with self.subTest(flag=flag, reason=reason):
                reads = len(self.host.pr_calls)
                rc, out, err = self.run_args("7", "--confirm", flag, reason)
                self.assertEqual(len(self.host.pr_calls), reads, "the reason was not refused before the host read: the run read the PR")
                self.assertEqual(rc, 1, out + err)
                self.assertIn(self.REWORD, err, "the refusal does not give the reword example")
                self.assertRegex(err, r"(?i)reword", "the refusal does not say to reword the reason")
                self.assertIsNone(merge.CLOSE_FORM.search(out + err), "the refusal prints a closing keyword before an issue ref or URL")
                self.assertNotIn("Traceback", err)

    def refusal_writes_nothing(self, flag, reason="fixes #2390"):
        """A refused reason stops the run before the lock, the claim, the merge and any host read. The PR is OPEN and green, so a run that gets past the reason merges it."""
        reads, refs = len(self.host.pr_calls), self.refs()
        rc, out, err = self.run_args("7", "--confirm", flag, reason)
        self.assertEqual(len(self.host.pr_calls), reads, "the reason was not refused before the host read: the run read the PR")
        self.assertFalse(self.lock_ref(), "the reason was not refused before the lock: the run took the merge lock")
        self.assertEqual(self.refs(), refs, "the run pushed to origin before the reason was refused")
        self.assertEqual(rc, 1, out + err)

    def test_close_keyword_base_red_ok_refuses_each_closing_form_before_the_host_read(self):
        self.refused_each("--base-red-ok", self.REFUSED)

    def test_close_keyword_undo_check_unknown_ok_refuses_each_closing_form_before_the_host_read(self):
        self.refused_each("--undo-check-unknown-ok", self.REFUSED)

    def test_close_keyword_base_red_ok_refuses_each_closing_issue_url_before_the_host_read(self):
        self.refused_each("--base-red-ok", self.REFUSED_URL)

    def test_close_keyword_undo_check_unknown_ok_refuses_each_closing_issue_url_before_the_host_read(self):
        self.refused_each("--undo-check-unknown-ok", self.REFUSED_URL)

    def test_close_keyword_base_red_ok_refused_reason_takes_no_lock_and_writes_nothing(self):
        self.refusal_writes_nothing("--base-red-ok")

    def test_close_keyword_undo_check_unknown_ok_refused_reason_takes_no_lock_and_writes_nothing(self):
        self.refusal_writes_nothing("--undo-check-unknown-ok")

    def test_close_keyword_base_red_ok_refused_issue_url_takes_no_lock_and_writes_nothing(self):
        self.refusal_writes_nothing("--base-red-ok", "fixes https://github.com/o/r/issues/2390")

    def test_close_keyword_undo_check_unknown_ok_refused_issue_url_takes_no_lock_and_writes_nothing(self):
        self.refusal_writes_nothing("--undo-check-unknown-ok", "fixes https://github.com/o/r/issues/2390")

    def reaches_host_read(self, *flag_reasons):
        """A run with these flag and reason pairs is not refused, so it reaches the PR's state read. The caller sets the PR CLOSED, so the run stops on the CLOSED line."""
        reads = len(self.host.pr_calls)
        rc, out, err = self.run_args("7", "--confirm", *flag_reasons)
        self.assertGreater(len(self.host.pr_calls), reads, "the reason was refused before the host read")
        self.assertIn("CLOSED", err, "the run did not reach the PR's state read")
        self.assertNotRegex(err, r"(?i)reword", "an allowed reason got the reword refusal")

    def test_close_keyword_allowed_reasons_reach_the_host_read_for_both_flags(self):
        # the controls: a reason with no closing form before a ref is not refused, so the run goes on to read the PR, which is CLOSED here
        self.host.pr_state = "CLOSED"
        for flag in self.FLAGS:
            for reason in self.ALLOWED:
                with self.subTest(flag=flag, reason=reason):
                    self.reaches_host_read(flag, reason)

    def test_close_keyword_pattern_has_no_adjacent_whitespace_repeats(self):
        # the cause: two repeats that both take the same whitespace run, with nothing required between them. A search backtracks over the run once for each split between them.
        found = adjacent_whitespace_repeats(merge.CLOSE_FORM.pattern)
        self.assertEqual(found, [], f"the closing-form pattern has two repeats that take the same whitespace run, with nothing required between them: {found}")

    def test_close_keyword_repeat_check_flags_each_respelling_and_passes_the_group_form(self):
        # the check's own pins, read from the parsed text: each two-run respelling is flagged, and the group form is not
        for pattern in (r"\s*:?\s*", r"\s*:{0,1}\s*", r"\s*[:-]?\s*"):
            with self.subTest(pattern=pattern):
                self.assertTrue(adjacent_whitespace_repeats(pattern), "the check does not flag a two-run respelling")
        self.assertEqual(adjacent_whitespace_repeats(r"\s*(?::\s*)?"), [], "the check flags the group form, which takes one run")

    def test_close_keyword_long_whitespace_run_keeps_its_result(self):
        # result only, no timing: a closing word with a long run and no ref after it is allowed, and the same run before a ref is refused
        cases = (("keyword, run, no ref", "fixes" + self.LONG_RUN + "x"),
                 ("keyword, run, #-less ref", "fixes" + self.LONG_RUN + "2390"),
                 ("bare keyword, run", "fix" + self.LONG_RUN),
                 ("keyword, run, colon, run, no ref", "fixes" + self.LONG_RUN[:10000] + ":" + self.LONG_RUN[:10000] + "x"))
        for label, text in cases:
            with self.subTest(case=label):
                self.assertIsNone(merge.CLOSE_FORM.search(text), "a closing word with a long run and no issue ref after it was refused")
        self.assertIsNotNone(merge.CLOSE_FORM.search("fixes" + self.LONG_RUN + "#2390"), "a closing word with a long run before an issue ref was allowed")

class GhHalf(Env):
    """Host against a `gh` shim on PATH. The shim merges into the local bare origin through the `other` clone."""
    def setUp(self):
        super().setUp()
        gh_case_setup(self)

    def set(self, **kw):
        p = os.path.join(self.state, "state.json")
        f = pathlib.Path(p)
        s = json.loads(f.read_text()) if f.exists() else {"other": self.other, "bare": self.bare, "checks_calls": 0}
        s.update(kw)
        f.write_text(json.dumps(s))

    def calls(self):
        p = pathlib.Path(self.state, "calls.log")
        return p.read_text() if p.exists() else ""  # a case that makes no gh call leaves no log

    def gh_host(self, required=("checks",), pause=None, ignore=None, minute=60):
        def tick(s):
            self.ticks += 1
            self.paused.append(s)
            assert self.ticks < 200, "the wait never ended"
            self.now += s
            if s in RATE_LADDER:  # a rate wait: what the lock on origin says as the wait starts (the clock is already at the wait's end)
                cur = self.lock.read("main")
                self.at_pause.append((s, self.now, cur[1] if cur else None))
            if pause:
                pause()
        return merge.Host(required if required == "protection" else list(required), "main", minute=minute, now=lambda: self.now, pause=tick, ignore=ignore)

    def go(self, **kw):
        return self.run_merge("7", "--confirm", host=self.gh_host(**kw))

    def test_a_red_main_run_read_through_gh_refuses_the_merge(self):
        # the red-main check's REST reads through the real gh call: one page of main's runs, then the red run's jobs
        push_base(self, {".github/workflows/checks.yml": MAIN_WORKFLOW})  # only a workflow file on main is judged
        self.set(base_runs=[main_run(901, "failure")], base_jobs={"901": [main_job("scope", "success"), main_job("checks", "failure", 20)]})
        rc, out = self.go()
        self.assertEqual(rc, 1, out)
        self.assertIn("run 901", out)
        self.assertIn("checks: fail", out)
        self.assertIn("GET actions/runs branch=main per_page=50", self.calls())
        self.assertNotIn("PUT pulls/7/merge", self.calls())

    def red_main_then_merge(self, *flags, unreadable=False):
        """Main's latest run is red, the flags go on the --confirm, and the merge call is the fake gh's. -> (rc, out, fields of each merge call)."""
        push_base(self, {".github/workflows/checks.yml": MAIN_WORKFLOW})
        self.set(base_runs=[main_run(901, "failure")], base_jobs={"901": [main_job("scope", "success"), main_job("checks", "failure", 20)]})
        with contextlib.ExitStack() as stack:
            if unreadable:
                stack.enter_context(UnknownOverride.unreadable(self))
            rc, out = self.run_merge("7", "--confirm", *flags, host=self.gh_host())
        return rc, out, self.gh_state("merge_fields") or []

    def test_a_base_red_lift_is_written_into_the_merge_commit_message(self):
        # a reason flag that lifts a check is kept: the merge call carries its line in commit_message
        rc, out, fields = self.red_main_then_merge("--base-red-ok", "this batch carries the checks fix")
        self.assertEqual(rc, 0, out)
        self.assertEqual(len(fields), 1, "the merge call was sent once, so the fields below are its")
        self.assertIn("commit_message", fields[0], "the lift is written into the merge commit message")
        self.assertEqual(set(fields[0]["commit_message"].splitlines()), {"Reason flag: --base-red-ok: this batch carries the checks fix"})

    def test_each_lift_writes_its_own_line_into_the_merge_commit_message(self):
        # both flags lift a check in one run: one line for each lift
        rc, out, fields = self.red_main_then_merge("--base-red-ok", "this batch carries the checks fix", "--undo-check-unknown-ok", "octopus read it", unreadable=True)
        self.assertEqual(rc, 0, out)
        self.assertEqual(len(fields), 1, "the merge call was sent once, so the fields below are its")
        self.assertIn("commit_message", fields[0], "both lifts are written into the merge commit message")
        self.assertEqual(set(fields[0]["commit_message"].splitlines()),
                         {"Reason flag: --base-red-ok: this batch carries the checks fix", "Reason flag: --undo-check-unknown-ok: octopus read it"})

    def test_no_commit_message_when_the_flags_lift_no_check(self):
        # the flags are given, but the base is green and the history readable: nothing is lifted, so GitHub's default message stays
        rc, out = self.run_merge("7", "--confirm", "--base-red-ok", "not needed here", "--undo-check-unknown-ok", "not needed here", host=self.gh_host())
        self.assertEqual(rc, 0, out)
        fields = self.gh_state("merge_fields") or []
        self.assertEqual(len(fields), 1, "the merge call was sent once, so the fields below are its")
        self.assertNotIn("commit_message", fields[0], "no check was lifted, so the merge carries no commit message")

    def test_no_commit_message_without_a_flag(self):
        rc, out = self.run_merge("7", "--confirm", host=self.gh_host())
        self.assertEqual(rc, 0, out)
        fields = self.gh_state("merge_fields") or []
        self.assertEqual(len(fields), 1, "the merge call was sent once, so the fields below are its")
        self.assertNotIn("commit_message", fields[0], "no flag was given, so the merge carries no commit message")

    def test_the_dropped_lane_lift_is_written_into_the_merge_commit_message(self):
        # the dropped-lane check's read is lifted by the same flag, so its line goes into the merge call too
        lane_batch(self, "lane1", "lane2")
        with CutLanes.first_lane_log_fails(self):
            rc, out = self.run_merge("7", "--confirm", "--undo-check-unknown-ok", "octopus read it", host=self.gh_host())
        self.assertEqual(rc, 0, out)
        self.assertIn("dropped-lane check UNKNOWN", out)  # the scope: the lift happened
        fields = self.gh_state("merge_fields") or []
        self.assertEqual(len(fields), 1, "the merge call was sent once, so the fields below are its")
        self.assertIn("commit_message", fields[0], "the dropped-lane lift is written into the merge commit message")
        self.assertEqual(set(fields[0]["commit_message"].splitlines()), {"Reason flag: --undo-check-unknown-ok: octopus read it"})

    def test_a_silent_undo_read_after_the_wait_lifted_by_the_reason_flag_is_written_into_the_merge_commit_message(self):
        # the first silent-undo read passes. The read in prove(), after the wait, cannot read the history, and the flag lifts it.
        # Only that read lifts, so its line is the one the merge call must carry.
        reason = "history read by hand after the wait"
        with UnknownOverride.unreadable_after_the_claim(self):
            rc, out = self.run_merge("7", "--confirm", "--undo-check-unknown-ok", reason, host=self.gh_host())
        self.assertEqual(rc, 0, out)
        self.assertIn("pushed to feat", out, "the claim moved the head, so the read after the wait scans again and is not the memo")
        self.assertEqual(out.count(f"--undo-check-unknown-ok, reason: {reason}"), 1, "the lift is logged once, by the read after the wait")
        fields = self.gh_state("merge_fields") or []
        self.assertEqual(len(fields), 1, "the merge call was sent once, so the fields below are its")
        self.assertIn("commit_message", fields[0], "the lift of the read after the wait is written into the merge commit message")
        self.assertEqual(set(fields[0]["commit_message"].splitlines()), {f"Reason flag: --undo-check-unknown-ok: {reason}"})

    def test_open_heads_lists_the_open_pr_heads_past_ghs_default_of_30(self):
        # A list read stops at its first page (30 rows by default) unless it asks for 100 a page and every page. A lane whose open PR is past row 30 would be deleted, and its PR closed.
        # Each head comes with its sha and its PR's base, {name: (sha, base)}, so the cut can tell the lane's own PR
        # (base = the batch's base) from a backport, and see a stacked PR whose base is a lane.
        self.set(open_prs=[["lane2", "a" * 40, "main"], ["agent/lane1", "b" * 40, "release/1.0"]])
        got = self.gh_host().open_heads()
        self.assertEqual(got, {"lane2": ("a" * 40, "main"), "agent/lane1": ("b" * 40, "release/1.0")})
        calls = self.calls()
        for part in (LIST_CALL, "state=open", "per_page=100"):  # one page holds 100 at most, so the read asks for each page by number
            self.assertIn(part, calls)

    def test_a_failed_open_pr_read_is_never_an_empty_set(self):
        # An empty set means no PR is open, and every lane would go. A failure stops (merge.Stop) or answers None.
        self.set(open_heads_fail="HTTP 404: Not Found")
        try:
            got = self.gh_host().open_heads()
        except merge.Stop:
            return
        self.assertIsNone(got)

    def test_the_pr_body_gh_reports_reaches_the_silent_undo_check_at_preview(self):
        # Host.pr reads the body in its read of the pull request (GET pulls/7), so a Drops-lines line in the body excuses its path.
        SilentUndo.stale_feat(self)
        self.set(body="Drops-lines: docs/decisions/first.md -- the lines are dead")
        rc, out = self.run_merge("7", host=self.gh_host())
        self.assertEqual(rc, 0, out)
        self.assertIn("ALLOWED docs/decisions/first.md: the lines are dead", out)
        self.assertIn("GET pulls/7", self.calls())

    def test_a_batch_with_lanes_reads_the_open_prs_through_gh_and_keeps_those_lanes(self):
        # Ruling 1: the open PR's head is a newer commit than lane2's tip, so lane2 is kept. Origin's lane2 stays at the tip.
        lane_batch(self, "agent/lane1", "lane2")
        self.set(open_prs=[["lane2", self.head("main"), "main"]])
